// IPROM Cosim用対応.
#define _SET_BYTE( dst, val , shift ) dst = dst | (val << shift)

// Lab変換用メモリマップ構造体.
typedef struct{
	uchar uc_Para0_L;
	uchar uc_Para0_H;
	uchar uc_Para1_L;
	uchar uc_Para1_H;
	uchar uc_Para2_L;
	uchar uc_Para2_H;
	uchar uc_Para3_L;
	uchar uc_Para3_H;
} LAB_MEMSET_TBL;

// XYZ用1/3乗テ－ブルの個数.
#define THRD_IPROM_XYZ_POW13TBL_MAX_NUM			4096
// RGB用指数テ－ブルの個数.
#define THRD_IPROM_RGB_SISUTBL_MAX_NUM			4096
// XYZ用3乗テ－ブルの個数.
#define THRD_IPROM_RGB_POW3TBL_MAX_NUM			1024
// RGB用逆指数テ－ブルの個数.
#define THRD_IPROM_RGB_REVSISUTBL_MAX_NUM		256

// 解像度変換用メモリマップ構造体.
typedef struct{
	uchar uc_Mem0;
	uchar uc_Mem1;
	uchar uc_Mem2;
	uchar uc_Mem3;
	uchar uc_Mem4;
	uchar uc_Mem5;
	uchar uc_Mem6;
	uchar uc_Mem7;
} RESOLCONV_MEMSET_TBL;

// 解像度変換テ－ブル ト－タルメモリセット回数.
#define THRD_IPROM_RESOLCONV_MEMSET_NUM		2


