{
	p_LUT_Switch_COLOR_IN	= S800_LUT_Switch_COLOR_IN;       // const uchar LUT_Switch_COLOR_IN[THRE_CmmMode_MAX];.
	p_LUT_Switch_COLOR_OUT	= S800_LUT_Switch_COLOR_OUT;      // const uchar LUT_Switch_COLOR_OUT[THRE_CmmMode_MAX][3];.
	p_White_Change_4DLUT	= S800_White_Change_4DLUT;        // const uchar White_Change_4DLUT[THRE_CmmMode_MAX][3];.
	p_V_Ratio_MONO			= S800_V_Ratio_MONO;              // const uchar V_Ratio_MONO[THRE_CmmMode_MAX][3];.
	p_Mono_Ratio_MONO		= S800_Mono_Ratio_MONO;           // const uchar XYZ2Lab[4][4];.
	p_XYZ2Lab				= S800_XYZ2Lab;                   // const uchar TableSignal[6];.
	p_TableSignal			= S800_TableSignal;               // const uchar Lab2XYZ[4][4];.
	p_Lab2XYZ				= S800_Lab2XYZ;                   // const uchar TableATR[6];.
	p_TableATR				= S800_TableATR;                  // const uchar OutputBus[6];.
	p_OutputBus				= S800_OutputBus;                 // const uchar RGB2XYZMatrix[6][18];.
	p_RGB2XYZMatrix			= S800_RGB2XYZMatrix;             // const uchar XYZ2RGBMatrix[6][18];.
	p_XYZ2RGBMatrix			= S800_XYZ2RGBMatrix;             // const uchar Mono_Ratio_MONO[THRE_CmmMode_MAX][3];.
	p_DOUT_Sel				= S800_DOUT_Sel;                  // const uchar DOUT_Sel[THRE_CmmMode_MAX];.
	p_V_Switch				= S800_V_Switch;                  // const uchar V_Switch[THRE_CmmMode_MAX][2];.
	p_Change_ATR			= S800_Change_ATR;                // const uchar Change_ATR[16][32];.
	p_LUT_Switch			= S800_LUT_Switch;                // const uchar LUT_Switch[16];.
	p_Screen_Mat_Cycle		= S800_Screen_Mat_Cycle;          // const uchar Screen_Mat_Cycle[16][2];.
	p_DIV_REF_SEL			= S800_DIV_REF_SEL;               // const uchar DIV_REF_SEL[16];.
	p_DIV_REF_Y				= S800_DIV_REF_Y;                 // const uchar * DIV_REF_Y[5];.
	p_M_Rand_Gen			= S800_M_Rand_Gen;                // const uchar M_Rand_Gen[16][4];.
	p_M_Rand_ExOr			= S800_M_Rand_ExOr;               // const uchar M_Rand_ExOr[16][4];.
	p_Select_FLT			= S800_Select_FLT;                // const uchar Select_FLT[16];.
	p_LabSendGain_La		= S800_LabSendGain_La;            // const unsigned char LabSendGain_La[6][4].
	p_LabSendGain_b			= S800_LabSendGain_b;             // const unsigned char LabSendGain_b[6][2].
	p_LabSendOffset			= S800_LabSendOffset;             // const unsigned char LabSendOffset[6][4].
	p_FaxDsel_Para			= S800_FaxDsel_Para;              // const uchar FaxDsel_Para[3][2].
	p_Jaggy_Para			= S800_Jaggy_Para;                // const uchar Jaggy_Para[3][13].
	p_MagInputSel_Para		= S800_MagInputSel_Para;          // const uchar MagInputSel_Para[3][2].
}

