//  17/04/07 Sky		ZeusSMLKPF対応.
// ================================================================================================.
uint32_t THRC_S800IPRomPara_ImageConv::getVSwitch( THRE_CmmMode e_mode )
{
	uint32_t ul_V_Switch = 0;
	for( int32_t i = 0; i < 2; i++ ){
		//! [][0]:領域外の論理設定 > "L":00h, "H":FFh.
		//! [][1]:明度データの種別選択 > 0:MIN(RGB), 1:RGB線形結合.
		ul_V_Switch |= p_V_Switch[e_mode][i] << (i * THRD_S800REG_SIFTNUM_16BIT);
	}
	return ul_V_Switch;
}

