// ================================================================================================.
//! <!--機能--> RGB→XYZ変換マトリクス係数設定レジスタの設定値を取得する.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//!	\param THRE_LabMode e_mode ......... Lab変換モード.
//! \param uchar uc_RegNo ..................... レジスタインデックス.
//! <!--戻値-->.
//! \return レジスタ設定値.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  13/03/12 Sky		機種共通化対応.
//  15/10/06 Sky		システム統合SoC(S800)対応.
//  17/04/07 Sky		ZeusSMLKPF対応.
// ================================================================================================.
uint32_t THRC_S800IPRomPara_ImageConv::getRGB2XYZMatrix( THRE_LabMode e_mode , uchar uc_RegNo )
{
	uint32_t ul_RGB2XYZMatrix = 0;
	int32_t index = 0;
	int32_t i;
	for( i = 1; i <= uc_RegNo; i++ ){
		if( i%2 != 0 ){
			index += 4;
		}else{
			index += 2;
		}
	}
	for( i=0; i<4; i++ ){
		if( uc_RegNo%2 == 0 || i < 2 ){
			// レジスタインデックスが奇数番号の場合は、上位16bitは0固定なので設定しない.
			ul_RGB2XYZMatrix |= p_RGB2XYZMatrix[e_mode][index++] << (i*8);
		}
	}
	return ul_RGB2XYZMatrix;
}


