{
	uint32_t ul_XYZ2RGBMatrix = 0;
	int32_t index = 0;
	int32_t i;
	for( i = 1; i <= uc_RegNo; i++ ){
		if( i%2 != 0 ){
			index += 4;
		}else{
			index += 2;
		}
	}
	for( i=0; i<4; i++ ){
		if( uc_RegNo%2 == 0 || i < 2 ){
			// レジスタインデックスが奇数番号の場合は、上位16bitは0固定なので設定しない.
			ul_XYZ2RGBMatrix |= p_XYZ2RGBMatrix[e_mode][index++] << (i*8);
		}
	}
	return ul_XYZ2RGBMatrix;
}

// ================================================================================================.
//! <!--機能--> Tiff-C ダイナミックレンジ パラメータを算出する ( Lab受信用 ).
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param float fl_gainUpperA ... 上限値A.
//! \param float fl_gainLowerA ... 下限値A.
//! \param float fl_gainUpperB ... 上限値B.
//! \param float fl_gainLowerB ... 下限値B.
//! <!--戻値-->.
//! \return ul_ReceiveGainOffset ... TIFF-Cフォーマット変換用ゲイン/オフセット係数.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  13/03/12 Sky		機種共通化対応.
//  15/10/06 Sky		システム統合SoC(S800)対応.
//  17/04/07 Sky		ZeusSMLKPF対応.
// ================================================================================================.
uint32_t THRC_S800IPRomPara_ImageConv::getReceiveGainParameter( float fl_gainUpperA, float fl_gainLowerA, float fl_gainUpperB, float fl_gainLowerB )
{

	uint32_t ul_ReceiveGainOffset = 0;

	// Lab送信時に設定するゲイン係数、オフセット係数をまずは算出する.

	// TIFF-Cフォーマット変換用ゲイン係数(a用)：AGAIN(送信用).
	// 送信時のゲイン係数を算出する.
	uint32_t ul_AGain = (uint32_t)(((255*256)/((fl_gainUpperA-fl_gainLowerA)*4095)*4096)+0.5);

	// TIFF-Cフォーマット変換用オフセット係数(a用)：AOFFSET(送信用).
	// 送信時のオフセット係数を算出する.
	uint32_t ul_AOffset = (uint32_t)(((fabs(fl_gainLowerA)/256*4096))+0.5);

	// TIFF-Cフォーマット変換用ゲイン係数(b用)：AGAIN(送信用).
	// 送信時のゲイン係数を算出する.
	uint32_t ul_BGain = (uint32_t)(((255*256)/((fl_gainUpperB-fl_gainLowerB)*4095)*4096)+0.5);

	// TIFF-Cフォーマット変換用オフセット係数(b用)：AOFFSET(送信用).
	// 送信時のオフセット係数を算出する.
	uint32_t ul_BOffset = (uint32_t)(((fabs(fl_gainLowerB)/256*4096))+0.5);


	// Lab送信時に設定するゲイン係数、オフセット係数を元にLab受信用の係数を算出する.

	// TIFF-Cフォーマット変換用ゲイン係数(a用)：AGAIN.
	uint32_t ul_ReceiveGainA = (uint32_t)(((1.0/(ul_AGain/4096.0)*(511.0/4095.0))*128.0)+0.5);
	THRL_ThAssert( ul_ReceiveGainA < (1<<8), "THRC_S800IPRomPara_ImageConv::getReceiveGainParameter(): ul_ReceiveGainA setting bit over!" , 0, 0, 0, 0, CFA14_DetailCode0x0C63 );
	ul_ReceiveGainOffset |= ul_ReceiveGainA;

	// TIFF-Cフォーマット変換用ゲイン係数(b用)：BGAIN.
	uint32_t ul_ReceiveGainB = (uint32_t)(((1.0/(ul_BGain/4096.0)*(511.0/4095.0))*128.0)+0.5);
	THRL_ThAssert( ul_ReceiveGainB < (1<<8), "THRC_S800IPRomPara_ImageConv::getReceiveGainParameter(): ul_ReceiveGainB setting bit over!" , 0, 0, 0, 0, CFA14_DetailCode0x0C64 );
	ul_ReceiveGainOffset |= ul_ReceiveGainB << 8;

	// TIFF-Cフォーマット変換用オフセット係数(a用)：AOFFSET.
	uint32_t ul_ReceiveOffsetA = (uint32_t)((ul_AOffset*ul_AGain/4096.0)+0.5);
	THRL_ThAssert( ul_ReceiveOffsetA < (1<<8), "THRC_S800IPRomPara_ImageConv::getReceiveGainParameter(): ul_ReceiveOffsetA setting bit over!" , 0, 0, 0, 0, CFA14_DetailCode0x0C65 );
	ul_ReceiveGainOffset |= ul_ReceiveOffsetA << 16;

	// TIFF-Cフォーマット変換用オフセット係数(b用)：BOFFSET.
	uint32_t ul_ReceiveOffsetB = (uint32_t)((ul_BOffset*ul_BGain/4096.0)+0.5);
	THRL_ThAssert( ul_ReceiveOffsetB < (1<<8), "THRC_S800IPRomPara_ImageConv::getReceiveGainParameter(): ul_ReceiveOffsetB setting bit over!" , 0, 0, 0, 0, CFA14_DetailCode0x0C66 );
	ul_ReceiveGainOffset |= ul_ReceiveOffsetB << 24;

	return ul_ReceiveGainOffset;
}


// ================================================================================================.
//! <!--機能--> TIFF-Cフォーマット変換用オフセット係数を算出する ( Lab受信用 ).
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param float fl_gainUpper ... 上限値.
//! \param float fl_gainLower ... 下限値.
//! <!--戻値-->.
//! \return ul_ReceiveOffset ... TIFF-Cフォーマット変換用オフセット係数.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  13/03/12 Sky		機種共通化対応.
//  15/10/06 Sky		システム統合SoC(S800)対応.
//  17/04/07 Sky		ZeusSMLKPF対応.
// ================================================================================================.
uint32_t THRC_S800IPRomPara_ImageConv::getReveiveGainOffset( float fl_gainUpper, float fl_gainLower )
{
	float fl_gainoffset = 0;
	uint32_t ul_ReceiveOffset = 0;
	
	fl_gainoffset = fl_gainUpper - fl_gainLower;
	
	if( fl_gainoffset != 0.0f ){
		// 分母が0でなければ演算.
		ul_ReceiveOffset = (uint32_t)((256 / fl_gainoffset) * fabs(fl_gainLower));
	}else{
		// 分母が0の場合は、0設定.
		ul_ReceiveOffset = 0L;
	}
	return ul_ReceiveOffset;
}



