// 070820 tadamasa Donau Lab送信対応 IPROM追加 (E).


// ================================================================================================.
//! <!--機能--> TIFF-C 白画像データを算出する.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param float fl_gainUpperA ... 上限値(A).
//! \param float fl_gainLowerA ... 下限値(A).
//! \param float fl_gainUpperB ... 上限値(B).
//! \param float fl_gainLowerB ... 下限値(B).
//! <!--戻値-->.
//! \return ul_InternalImage   ... 内部生成画像データ(8bit).
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  13/03/12 Sky		機種共通化対応.
//  15/10/06 Sky		システム統合SoC(S800)対応.
//  17/04/07 Sky		ZeusSMLKPF対応.
// ================================================================================================.
uint32_t THRC_S800IPRomPara_ImageConv::getInternalImageData( float fl_gainUpperA, float fl_gainLowerA, float fl_gainUpperB, float fl_gainLowerB )
{
	uint32_t ul_InternalImage = 0;

	// 白データ(L).
	uint32_t ul_InternalImageL = 0x000000FF; 
	ul_InternalImage |= ul_InternalImageL; 
	// 白データ(A).
	uint32_t ul_InternalImageA = getInternalData( fl_gainUpperA, fl_gainLowerA );
	THRL_ThAssert( ul_InternalImageA < (1<<8), "THRC_S800IPRomPara_ImageConv::getInternalImageData(): ul_InternalImageA setting bit over!" , 0, 0, 0, 0, CFA14_DetailCode0x0C67 ); 
	ul_InternalImage |= ul_InternalImageA << 8; 
	// 白データ(B).
	uint32_t ul_InternalImageB = getInternalData( fl_gainUpperB, fl_gainLowerB );
	THRL_ThAssert( ul_InternalImageB < (1<<8), "THRC_S800IPRomPara_ImageConv::getInternalImageData(): ul_InternalImageB setting bit over!" , 0, 0, 0, 0, CFA14_DetailCode0x0C68 ); 
	ul_InternalImage |= ul_InternalImageB << 16; 
	
	return ul_InternalImage;
} 


// ================================================================================================.
//! <!--機能--> TIFF-C 白画像データ(A/B)を算出する ( Lab受信用 ).
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param float fl_gainUpper ... 上限値.
//! \param float fl_gainLower ... 下限値.
//! <!--戻値-->.
//! \return ul_InternalImage ... 内部生成画像データ(8bit).
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  13/03/12 Sky		機種共通化対応.
//  15/10/06 Sky		システム統合SoC(S800)対応.
//  17/04/07 Sky		ZeusSMLKPF対応.
// ================================================================================================.
uint32_t THRC_S800IPRomPara_ImageConv::getInternalData( float fl_gainUpper, float fl_gainLower )
{
	float fl_gainimage = 0;
	uint32_t ul_InternalImage = 0;
	
	fl_gainimage = fl_gainUpper - fl_gainLower;

	if( fl_gainimage != 0.0f ){
		// 分母が0でなければ演算.
		ul_InternalImage = (uint32_t)( ceil((255*( 0 - fl_gainLower )) / fl_gainimage ));
	}
	else{
		// 分母が0の場合は、0設定.
		ul_InternalImage = (uint32_t)0L;
	}
	return ul_InternalImage;
}

// ================================================================================================.
//! <!--機能--> 倍率を取得する(解像度変換レジスタ用).
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param float ..... 倍率X(スレッドより指定).
//! \param float ..... 倍率Y(スレッドより指定).
//! \param float* .... 倍率X(解像度変換レジスタ設定処理用).
//! \param float* .... 倍率Y(解像度変換レジスタ設定処理用).
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  13/03/12 Sky		機種共通化対応.
//  15/10/06 Sky		システム統合SoC(S800)対応.
//  17/04/07 Sky		ZeusSMLKPF対応.
// ================================================================================================.
void THRC_S800IPRomPara_ImageConv::getMagnification( float sf_RatioX, float sf_RatioY, float* sf_UseRatioX, float* sf_UseRatioY )
{
	float sf_RX = 0;
	float sf_RY = 0;

	// 倍率X取得.
	if( sf_RatioX >= 1.0f ){
		// 拡大時.
		sf_RX = (float)(ceil( 4096.0f / sf_RatioX ) -1);
		*sf_UseRatioX  = ( 4096.0f / (sf_RX + 1) );
	}else{
		// 縮小時.
		sf_RX = (float)(ceil( sf_RatioX * 4096.0f ) -1);
		*sf_UseRatioX  = ( ( sf_RX + 1 ) / 4096.0f );
	}

	// 倍率Y取得.
	if( sf_RatioY >= 1.0f ){
		// 拡大時.
		sf_RY = (float)(ceil( 4096.0f / sf_RatioY ) -1);
		*sf_UseRatioY  = ( 4096.0f / (sf_RY + 1) );
	}else{
		// 縮小時.
		sf_RY = (float)(ceil( sf_RatioY * 4096.0f ) -1);
		*sf_UseRatioY  = ( ( sf_RY + 1 ) / 4096.0f );
	}
}

// ================================================================================================.
//! <!--機能--> 解像度変換 がたつき補正設定レジスタ設定値を取得.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param THRE_JaggyCorrectMode e_mode ... がたつき補正モード.
//! <!--戻値-->.
//! \return   解像度変換 がたつき補正設定レジスタ設定値.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  13/03/12 Sky		機種共通化対応.
//  15/10/06 Sky		システム統合SoC(S800)対応.
//  17/04/07 Sky		ZeusSMLKPF対応.
//  24/03/22 FPT		Fix build error GccVersionUp.
// ================================================================================================.
uint32_t THRC_S800IPRomPara_ImageConv::getJaggyCorrect( THRE_JaggyCorrectMode e_mode )
{
	uint32_t ul_JaggyCorrect = 0;
	uchar i = 0;
	
	for( i = 0; i < THRD_S800REG_SETNUM_2BYTE; i++ ){
		ul_JaggyCorrect |= p_FaxDsel_Para[e_mode][i] << (i * THRD_S800REG_SIFTNUM_8BIT);
	}
	ul_JaggyCorrect |= p_Jaggy_Para[e_mode][0] << (i * THRD_S800REG_SIFTNUM_8BIT);
	
	return ul_JaggyCorrect;
}

