//  17/04/07 Sky		ZeusSMLKPF対応.
// ================================================================================================.
uint32_t THRC_S800IPRomPara_ImageConv::getScreenMatCycle( THRE_BinarizerMode e_mode )
{
	uint32_t ul_NoiseMat = 0;
	 uchar i;
	for( i=0; i<THRD_S800REG_SETNUM_2BYTE; i++ ){ 
		ul_NoiseMat |= p_Screen_Mat_Cycle[e_mode][i] << (i * THRD_S800REG_SIFTNUM_8BIT);
	}
	// 16,17bit目に2値化リファレンス固定値選択を設定.
	ul_NoiseMat |= p_DIV_REF_SEL[e_mode] << (i * 8);
	return ul_NoiseMat;
}

