// ================================================================================================.
//! <!--機能--> バイキュービック演算を行う.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param float ..... 倍率.
//! \param ulong* .... 設定レジスタ0.
//! \param ulong* .... 設定レジスタ1.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  13/03/12 Sky		機種共通化対応.
//  15/10/06 Sky		システム統合SoC(S800)対応.
//  17/04/07 Sky		ZeusSMLKPF対応.
// ================================================================================================.
void THRC_S800IPRomPara_ImageConv::setBiCubic( float sf_Ratio, uint32_t* pul_Reg0, uint32_t* pul_Reg1 )
{
	float	sf_Shift	= 0.0f;
	float	sf_Buf1		= 0.0f;
	float	sf_Buf2		= 0.0f;
	float	sf_Buf3		= 0.0f;
	int32_t	sl_Wnp2		= 0L;
	int32_t	sl_Wnp1		= 0L;
	int32_t	sl_Wn		= 0L;
	int32_t	sl_Wnm1		= 0L;
	int32_t	sl_Tot		= 0L;

	// シフト量の算出.
	if( sf_Ratio>=1.0f ){
		sf_Shift = 0.0f;
	}else if( (1-sf_Ratio)<=0.5f ){
		sf_Shift = 1-sf_Ratio;
	}else{
		sf_Shift = 0.5f;
	}

	// W(n+2)の算出.
	sf_Buf1 = 2-sf_Shift;
	sf_Buf2 = sf_Buf1 * sf_Buf1;
	sf_Buf3 = sf_Buf2 * sf_Buf1;
	sl_Wnp2	= (int32_t)half_Adjust(((-sf_Buf3)+(5*sf_Buf2)-((8*sf_Buf1)+4))*0x8000);


	// W(n+1)の算出.
	sf_Buf1 = 1-sf_Shift;
	sf_Buf2 = sf_Buf1 * sf_Buf1;
	sf_Buf3 = sf_Buf2 * sf_Buf1;
	sl_Wnp1	= (int32_t)half_Adjust(((sf_Buf3)-(2*sf_Buf2)+1)*0x8000);


	// W(n)の算出.
	sf_Buf1 = sf_Shift;
	sf_Buf2 = sf_Buf1 * sf_Buf1;
	sf_Buf3 = sf_Buf2 * sf_Buf1;
	sl_Wn	= (int32_t)half_Adjust(((sf_Buf3)-(2*sf_Buf2)+1)*0x8000);


	// W(n-1)の算出.
	sf_Buf1 = 1+sf_Shift;
	sf_Buf2 = sf_Buf1 * sf_Buf1;
	sf_Buf3 = sf_Buf2 * sf_Buf1;
	sl_Wnm1	= (int32_t)half_Adjust(((-sf_Buf3)+(5*sf_Buf2)-((8*sf_Buf1)+4))*0x8000);


	sl_Tot = sl_Wnp1 + sl_Wnp2 + sl_Wnm1 + sl_Wn;

	// バイキュービック演算結果が常に32768以上(補間係数が100%の値)になるように設定.
	if( sl_Tot < 32768 ){
		sl_Wnp1 = sl_Wnp1 + ( 32768 - sl_Tot );
	}

	// 計算結果をレジスタにセット.
	*pul_Reg0 = ((sl_Wnp1  &0xffff)<<16)+(sl_Wnp2&0xffff);
	*pul_Reg1 = ((sl_Wnm1&0xffff)<<16)+(sl_Wn&0xffff);
}

// ================================================================================================.
//! <!--機能--> バイキュービック演算：四捨五入.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param float ..... バイキュービック演算結果 (float).
//! <!--戻値-->.
//! \return            四捨五入後の値。.
//! <!--詳細-->.
//! バイキュービック演算の結果に対して四捨五入を行う。.
//! <!--履歴-->.
//  13/03/12 Sky		機種共通化対応.
//  15/10/06 Sky		システム統合SoC(S800)対応.
//  17/04/07 Sky		ZeusSMLKPF対応.
// ================================================================================================.
short THRC_S800IPRomPara_ImageConv::half_Adjust( float sf_Input )
{
	if( sf_Input > 32767 ){
		return 32767;
	}else if( sf_Input < 0 ){
		return (short)(sf_Input-0.5); // 四捨五入.
	}else{
		return (short)(sf_Input+0.5); // 四捨五入.
	}
}

// ================================================================================================.
//! <!--機能--> 拡大率演算を行う.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param float ..... 倍率.
//! \param ulong* .... 設定レジスタ.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  13/03/12 Sky		機種共通化対応.
//  15/10/06 Sky		システム統合SoC(S800)対応.
//  17/04/07 Sky		ZeusSMLKPF対応.
// ================================================================================================.
void THRC_S800IPRomPara_ImageConv::setMagnification( float sf_Ratio, uint32_t* pul_Reg )
{
	uint32_t	ul_Buf	= 0L;

	if( sf_Ratio > 1.0f ){
		// 拡大時：（４０９６／拡大率）－１.
		ul_Buf  = (uint32_t)ceil(4096.0f / sf_Ratio) - 1;
		// 拡大時：MAGMPXビットをＯＮ.
		ul_Buf |= (1<<12);
	}else{
		// 縮小時：（縮小率×４０９６）－１.
		ul_Buf  = (uint32_t)(sf_Ratio * 4096.0f) - 1;
	}

	// 計算結果をレジスタにセット.
	*pul_Reg = (ul_Buf) & ((1<<13)-1);
}

// ================================================================================================.
//! <!--機能--> イメージリピート量演算を行う.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param float ..... 倍率.
//! \param ulong ..... 出力画像サイズ（主走査）.
//! \param ulong* .... 設定レジスタ.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  13/03/12 Sky		機種共通化対応.
//  15/10/06 Sky		システム統合SoC(S800)対応.
//  17/04/07 Sky		ZeusSMLKPF対応.
// ================================================================================================.
void THRC_S800IPRomPara_ImageConv::setImageRepeat( float sf_Ratio, uint32_t ul_Size, uint32_t* pul_Reg )
{
	uint32_t	ul_Buf	= 0L;

	if( sf_Ratio > 1.0f ){
		// 拡大時：イレース量設定 = 出力画像サイズ - 1.
		ul_Buf  = (ul_Size - 1) << 16;
		// 拡大時：イメージリピート量設定.
		ul_Buf |= ((ul_Size + 51) & 0xffff);
	}else{
		// 縮小時.
		ul_Buf  = 0xfffeffffL;
	}

	// 計算結果をレジスタにセット.
	*pul_Reg = ul_Buf;
}

// ================================================================================================.
//! <!--機能--> ニアレストネイバー拡大率演算を行う.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param float ..... 倍率.
//! \param ulong* .... 設定レジスタ.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  13/03/12 Sky		機種共通化対応.
//  15/10/06 Sky		システム統合SoC(S800)対応.
//  17/04/07 Sky		ZeusSMLKPF対応.
// ================================================================================================.
void THRC_S800IPRomPara_ImageConv::setNearestNeighbor( float sf_Ratio, uint32_t* pul_Reg )
{
	uint32_t	ul_Buf	= 0L;

	// ニアレストネイバー拡大率整数部（小数切捨処理）.
	ul_Buf = ((uint32_t)ceil(sf_Ratio))-1L;
	
	ul_Buf &= 0x0000000fL;

	if( sf_Ratio >= 1.0f ){
		// 拡大時.
		ul_Buf |= 0x00000020L;
	}else{
		// 縮小時.
		ul_Buf |= 0x00000010L;
	}

	// 計算結果をレジスタにセット.
	*pul_Reg = (ul_Buf) | (0x000000c0L);
}

// ================================================================================================.
//! <!--機能--> 副走査繰り返し回数演算を行う.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param float ..... 倍率.
//! \param ulong* .... 設定レジスタ.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  13/03/12 Sky		機種共通化対応.
//  15/10/06 Sky		システム統合SoC(S800)対応.
//  17/04/07 Sky		ZeusSMLKPF対応.
// ================================================================================================.
void THRC_S800IPRomPara_ImageConv::setVerticalRepeat( float sf_Ratio, uint32_t* pul_Reg )
{
	uint32_t	ul_Buf	= 0L;

	// 副走査繰り返し回数（小数切捨処理）.
	ul_Buf = ((uint32_t)ceil(sf_Ratio))-1L;

	// 計算結果をレジスタにセット.
	*pul_Reg = ul_Buf;
}

// ================================================================================================.
//! <!--機能--> 出力側主走査トリミング位置設定レジスタを取得する.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param ulong  ..... サイズ( 画像データ：出力画像サイズ / TAGデータ：入力画像サイズ).
//! \param ulong* ..... レジスタ値.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  13/03/12 Sky		機種共通化対応.
//  15/10/06 Sky		システム統合SoC(S800)対応.
//  17/04/07 Sky		ZeusSMLKPF対応.
// ================================================================================================.
void THRC_S800IPRomPara_ImageConv::setMagnificationTrmg( uint32_t ul_ImageSize, uint32_t* pul_Reg )
{
	uint32_t ul_END6P = 0;
	ul_END6P = 0x0000001d;	
	*pul_Reg = (uint32_t)(((((ul_ImageSize + ul_END6P) - ul_END6P) - 1) & 0xffff) << 16) | ul_END6P;
}

// ================================================================================================.
//! <!--機能--> イメージ合成情報を設定する.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param ulong  ..... 色種類.
//! \param ulong* ..... 合成濃度情報.
//! <!--戻値-->.
//! \return 濃度.
//! <!--詳細-->.
//! 画像合成する属性データの数だけ、この関数を利用して画像合成用の各種情報を設定する。\n.
//! 合成できる画像は最大４つ。\n.
//! 画像合成の優先度は、属性0->3の順番固定となる。\n.
//! <!--履歴-->.
//  13/03/12 Sky		機種共通化対応.
//  15/10/06 Sky		システム統合SoC(S800)対応.
//  17/04/07 Sky		ZeusSMLKPF対応.
// ================================================================================================.
//イメージ合成用パラメータ(Lab変換用).
//Lab変換を前提にした色表現の値.
static uchar	uc_addImageCompositorDensityKCMY[7][4] = {
{ 0x00, 0xff, 0xff, 0xff },		// 黒.
{ 0x00, 0x1f, 0xff, 0xff },		// 赤.
{ 0x00, 0xff, 0x5f, 0xdf },		// 緑.
{ 0x00, 0xff, 0xff, 0x5f },		// 青.
{ 0x00, 0x00, 0x00, 0xff },		// 黄.
{ 0x00, 0x27, 0xff, 0x27 },		// マゼンタ.
{ 0x00, 0xff, 0x63, 0x27 },		// シアン.
};

uint32_t THRC_S800IPRomPara_ImageConv::addImageCompositorInfo( TYPE_ColorKind e_ColorKind, TYPE_StampDensity e_StampDensity, Bool b_LabConvOrg )
{
	register uint32_t ul_CompositData = 0;
	register uchar uc_Density = 0;
	register uchar uc_TableSel = 0;

	// 濃度設定算出.
	switch( e_StampDensity ){
	case TYPE_StampDensityD1:	// やや濃い.
	case TYPE_StampDensityD2:	// 濃い.
		uc_Density = 0xFF;
		break;
	case TYPE_StampDensityN:	// 普通.
		uc_Density = 0xA6;
		break;
	case TYPE_StampDensityL1:	// 淡い.
		uc_Density = 0x66;
		break;
	default:
		THRL_ThAssert( (Bool)(False), "THRC_S800IPRomPara_ImageConv::addImageCompositorInfo(): addImageCompositorInfo  e_StampDensity = %d" ,e_StampDensity, 0, 0, 0 , CFA14_DetailCode0x0C69 );
		break;
	}

	// 置換データ設定算出.
	if( b_LabConvOrg == False ){
		//カラー以外のデータを受信した際はLab変換が行われないため、.
		//カラーのデータを受信したI-FAX送信 カラー/グレーのスタンプ以外は従来通りの処理とする.
		switch(e_ColorKind){
			case TYPE_ColorKind_Black:		//黒 (CMYで表現).
				ul_CompositData |= (uc_Density);
				ul_CompositData |= (uc_Density << 8);
				ul_CompositData |= (uc_Density << 16);
				break;
			case TYPE_ColorKind_Red:		//赤 (MYで表現).
				ul_CompositData |= (uc_Density);
				ul_CompositData |= (uc_Density << 8);
				break;
			case TYPE_ColorKind_Green:		//緑 (CYで表現).
				ul_CompositData |= (uc_Density);
				ul_CompositData |= (uc_Density << 16);
				break;
			case TYPE_ColorKind_Blue:		//青 (CMで表現).
				ul_CompositData |= (uc_Density << 8);
				ul_CompositData |= (uc_Density << 16);
				break;
			case TYPE_ColorKind_Yellow:		//黄色 (Yで表現).
				ul_CompositData |= (uc_Density);
				break;
			case TYPE_ColorKind_Magenta:	//マゼンタ (Mで表現).
				ul_CompositData |= (uc_Density << 8);
				break;
			case TYPE_ColorKind_Cyan:		//シアン (Cで表現).
				ul_CompositData |= (uc_Density << 16);
				break;
			default:
				THRL_ThAssert( (Bool)(False), "THRC_S800IPRomPara_ImageConv::addImageCompositorInfo(): addImageCompositorInfo Error ColorKind is invalid data!!", 0, 0, 0, 0 , CFA14_DetailCode0x0C6A );
				break;
		}
	}else{
		// I-FAXのスタンプ.
		switch(e_ColorKind){
			case TYPE_ColorKind_Black:		//黒.
				uc_TableSel = 0;
				break;
			case TYPE_ColorKind_Red:		//赤.
				uc_TableSel = 1;
				break;
			case TYPE_ColorKind_Green:		//緑.
				uc_TableSel = 2;
				break;
			case TYPE_ColorKind_Blue:		//青.
				uc_TableSel = 3;
				break;
			case TYPE_ColorKind_Yellow:		//黄.
				uc_TableSel = 4;
				break;
			case TYPE_ColorKind_Magenta:	//マゼンタ.
				uc_TableSel = 5;
				break;
			case TYPE_ColorKind_Cyan:		//シアン.
				uc_TableSel = 6;
				break;
			default:
				THRL_ThAssert( False, "addImageCompositorInfo Error ColorKind is invalid data!!" , 0, 0, 0, 0, CFA14_DetailCode0x0C6B );
				uc_TableSel = 0;
				break;
		}
		ul_CompositData |= (uc_addImageCompositorDensityKCMY[uc_TableSel][0] << 24);	// K.
		ul_CompositData |= (uc_addImageCompositorDensityKCMY[uc_TableSel][1] << 16);	// C.
		ul_CompositData |= (uc_addImageCompositorDensityKCMY[uc_TableSel][2] << 8);		// M.
		ul_CompositData |= uc_addImageCompositorDensityKCMY[uc_TableSel][3];			// Y.
	}
	return ul_CompositData;
}

