// ================================================================================================.
//! <!--機能--> CMMテーブルデータの先頭アドレスを取得する.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param THRE_CmmMode e_mode ... CMM画像変換モード.
//! <!--戻値-->.
//! \return CMMテーブルデータの先頭アドレス.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  09/08/07 越野	 Donau環境から分離して作成.
//  15/10/06 Sky	 システム統合SoC(S800)対応.
//  17/04/07 Sky	 ZeusSMLKPF対応.
// ================================================================================================.
const uchar* THRC_S800IPRomPara_ImageConv::getCmmTableAddress( THRE_CmmMode e_mode )
{
	return &uc_4DTbl0[0];
}

// ================================================================================================.
//! <!--機能--> Logテーブルデータの先頭アドレスを取得する.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param THRE_CmmMode e_mode ... CMM画像変換モード.
//! <!--戻値-->.
//! \return ログテーブルデータの先頭アドレス.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  09/08/07 越野	 Donau環境から分離して作成.
//  15/10/06 Sky	 システム統合SoC(S800)対応.
//  17/04/07 Sky	 ZeusSMLKPF対応.
// ================================================================================================.
const uchar* THRC_S800IPRomPara_ImageConv::getLogTableAddress( THRE_CmmMode e_mode )
{
	uchar ucNo = S800_MSel_Log[e_mode];
#ifdef SIMULATOR
	THRL_SetThLog( 656, THRE_DebugLogType_CTLog, 0, True, (uintptr_t)"Log table data", ucNo, e_mode );
#endif
	return &S800_LOG_LUT[ucNo][0];
}

// ================================================================================================.
//! <!--機能--> Lab・XYZ用1/3乗テーブルデータの先頭アドレスを取得する.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param THRE_LabMode e_mode ... Lab変換モ－ド.
//! <!--戻値-->.
//! \return.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  09/08/07 越野	 Donau環境から分離して作成.
//  15/10/06 Sky	システム統合SoC(S800)対応.
//  17/04/07 Sky	ZeusSMLKPF対応.
// ================================================================================================.
// XYZ用1/3乗テ－ブル.
static LAB_MEMSET_TBL	st_XYZ_Pow1_3_Tbl[THRD_IPROM_XYZ_POW13TBL_MAX_NUM];
// RGB用指数テ－ブル.
static LAB_MEMSET_TBL	st_RGB_Sisu_Tbl[THRD_IPROM_RGB_SISUTBL_MAX_NUM];
// XYZ用3乗テ－ブル.
static LAB_MEMSET_TBL	st_XYZ_Pow3_Tbl[THRD_IPROM_RGB_POW3TBL_MAX_NUM];
// RGB用逆指数テ－ブル.
static LAB_MEMSET_TBL	st_RGB_RevSisu_Tbl[THRD_IPROM_RGB_REVSISUTBL_MAX_NUM];

const uchar* THRC_S800IPRomPara_ImageConv::getLabTableAddress_XYZ_Pow1_3(  THRE_LabMode e_mode )
{
	uchar uc_No = S800_Msel_Send[e_mode];

#ifdef SIMULATOR
	THRL_SetThLog( 656, THRE_DebugLogType_CTLog, 0, True, (uintptr_t)"Lab - XYZ POW1/3 table data", uc_No, e_mode );
#endif
	
	// ASIC内のLAB変換用メモリマップに従いテ－ブルデ－タを設定.
	for( ushort us_Index =0; us_Index < THRD_IPROM_XYZ_POW13TBL_MAX_NUM; us_Index++ ){
		st_XYZ_Pow1_3_Tbl[us_Index].uc_Para0_L = S800_XYZ_X_TBL_L_Send[uc_No][us_Index];
		st_XYZ_Pow1_3_Tbl[us_Index].uc_Para0_H = S800_XYZ_X_TBL_H_Send[uc_No][us_Index];
		st_XYZ_Pow1_3_Tbl[us_Index].uc_Para1_L = S800_XYZ_Y_TBL_L_Send[uc_No][us_Index];
		st_XYZ_Pow1_3_Tbl[us_Index].uc_Para1_H = S800_XYZ_Y_TBL_H_Send[uc_No][us_Index];
		st_XYZ_Pow1_3_Tbl[us_Index].uc_Para2_L = S800_XYZ_Z_TBL_L_Send[uc_No][us_Index];
		st_XYZ_Pow1_3_Tbl[us_Index].uc_Para2_H = S800_XYZ_Z_TBL_H_Send[uc_No][us_Index];
		st_XYZ_Pow1_3_Tbl[us_Index].uc_Para3_L = 0;
		st_XYZ_Pow1_3_Tbl[us_Index].uc_Para3_H = 0;
	}
	return (uchar*)&st_XYZ_Pow1_3_Tbl[0];
}

// ================================================================================================.
//! <!--機能--> Lab・RGB用指数テーブルデータの先頭アドレスを取得する.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param THRE_LabMode e_mode ... Lab変換モ－ド.
//! <!--戻値-->.
