const uchar* THRC_S800IPRomPara_ImageConv::getLabTableAddress_RGB_Sisu(  THRE_LabMode e_mode )
{
	uchar uc_No = S800_Msel_Receive[e_mode];

#ifdef SIMULATOR
	THRL_SetThLog( 656, THRE_DebugLogType_CTLog, 0, True, (uintptr_t)"Lab - RGB Index table data", uc_No, e_mode );
#endif
	
	// ASIC内のLAB変換用メモリマップに従いテ－ブルデ－タを設定.
	for( ushort us_Index =0; us_Index < THRD_IPROM_RGB_SISUTBL_MAX_NUM; us_Index++ ){
		st_RGB_Sisu_Tbl[us_Index].uc_Para0_L = S800_RGB_TBL_L_Receive[uc_No][us_Index];
		st_RGB_Sisu_Tbl[us_Index].uc_Para0_H = S800_RGB_TBL_H_Receive[uc_No][us_Index];
		st_RGB_Sisu_Tbl[us_Index].uc_Para1_L = S800_RGB_TBL_L_Receive[uc_No][us_Index];
		st_RGB_Sisu_Tbl[us_Index].uc_Para1_H = S800_RGB_TBL_H_Receive[uc_No][us_Index];
		st_RGB_Sisu_Tbl[us_Index].uc_Para2_L = S800_RGB_TBL_L_Receive[uc_No][us_Index];
		st_RGB_Sisu_Tbl[us_Index].uc_Para2_H = S800_RGB_TBL_H_Receive[uc_No][us_Index];
		st_RGB_Sisu_Tbl[us_Index].uc_Para3_L = 0;
		st_RGB_Sisu_Tbl[us_Index].uc_Para3_H = 0;
	}
	return (uchar*)&st_RGB_Sisu_Tbl[0];
}

