		st_XYZ_Pow3_Tbl[us_Index].uc_Para2_L = S800_XYZ_Z_TBL_L_Receive[uc_No][us_Index];
		st_XYZ_Pow3_Tbl[us_Index].uc_Para2_H = S800_XYZ_Z_TBL_H_Receive[uc_No][us_Index];
