// ================================================================================================.
//! <!--機能--> 解像度変換用テ－ブルデ－タの先頭アドレスを取得する.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param なし.
//! <!--戻値-->.
//! \return.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  09/08/07 越野	 Donau環境から分離して作成.
//  10/02/22 世古	 ASIC改版対応用の新旧テーブル切り替え処理を削除し、常に新テーブル値を設定するよう修正(CQ:324158).
//  17/04/07 Sky	 ZeusSMLKPF対応.
// ================================================================================================.
// 解像度変換 メモリ設定テ－ブル.
static RESOLCONV_MEMSET_TBL		st_ResolConv_MemSet_Tbl[THRD_IPROM_RESOLCONV_MEMSET_NUM][THRD_IPROM_RESOLCONV_ONEMEM_SIZE];

const uchar* THRC_S800IPRomPara_ImageConv::getResolutionConvertTableAddress()
{
	// ASIC内の解像度変換用メモリマップに従いテ－ブルデ－タを設定.
	ushort us_MemIndex = 0;
	for( us_MemIndex = 0; us_MemIndex < THRD_IPROM_RESOLCONV_ONEMEM_SIZE; us_MemIndex++ ){
		// 主走査拡大補間 BICUBIC補間係数変換メモリ設定.
		st_ResolConv_MemSet_Tbl[0][us_MemIndex].uc_Mem0 = S800_Bicubic_Mem_NA_L[us_MemIndex];	
		st_ResolConv_MemSet_Tbl[0][us_MemIndex].uc_Mem1 = S800_Bicubic_Mem_NA_H[us_MemIndex];
		st_ResolConv_MemSet_Tbl[0][us_MemIndex].uc_Mem2 = S800_Bicubic_Mem_NB_L[us_MemIndex];
		st_ResolConv_MemSet_Tbl[0][us_MemIndex].uc_Mem3 = S800_Bicubic_Mem_NB_H[us_MemIndex];
		st_ResolConv_MemSet_Tbl[0][us_MemIndex].uc_Mem4 = S800_Bicubic_Mem_NC_L[us_MemIndex];
		st_ResolConv_MemSet_Tbl[0][us_MemIndex].uc_Mem5 = S800_Bicubic_Mem_NC_H[us_MemIndex];
		st_ResolConv_MemSet_Tbl[0][us_MemIndex].uc_Mem6 = S800_Bicubic_Mem_ND_L[us_MemIndex];
		st_ResolConv_MemSet_Tbl[0][us_MemIndex].uc_Mem7 = S800_Bicubic_Mem_ND_H[us_MemIndex];
	}
	for( us_MemIndex = 0; us_MemIndex < THRD_IPROM_RESOLCONV_ONEMEM_SIZE; us_MemIndex++ ){
		// 副走査拡大補間 BICUBIC補間係数変換メモリ設定.
		st_ResolConv_MemSet_Tbl[1][us_MemIndex].uc_Mem0 = S800_Bicubic_Reso_Mem_NA_L[us_MemIndex];	
		st_ResolConv_MemSet_Tbl[1][us_MemIndex].uc_Mem1 = S800_Bicubic_Reso_Mem_NA_H[us_MemIndex];
		st_ResolConv_MemSet_Tbl[1][us_MemIndex].uc_Mem2 = S800_Bicubic_Reso_Mem_NB_L[us_MemIndex];
		st_ResolConv_MemSet_Tbl[1][us_MemIndex].uc_Mem3 = S800_Bicubic_Reso_Mem_NB_H[us_MemIndex];
		st_ResolConv_MemSet_Tbl[1][us_MemIndex].uc_Mem4 = S800_Bicubic_Reso_Mem_NC_L[us_MemIndex];
		st_ResolConv_MemSet_Tbl[1][us_MemIndex].uc_Mem5 = S800_Bicubic_Reso_Mem_NC_H[us_MemIndex];
		st_ResolConv_MemSet_Tbl[1][us_MemIndex].uc_Mem6 = S800_Bicubic_Reso_Mem_ND_L[us_MemIndex];
		st_ResolConv_MemSet_Tbl[1][us_MemIndex].uc_Mem7 = S800_Bicubic_Reso_Mem_ND_H[us_MemIndex];
	}

//	// ASIC内の解像度変換用メモリマップに従いテ－ブルデ－タを設定.
//	for( uchar uc_MemSetNum =0; uc_MemSetNum < THRD_IPROM_RESOLCONV_MEMSET_NUM; uc_MemSetNum++ ){.
//		for( ushort us_MemIndex = 0; us_MemIndex < THRD_IPROM_RESOLCONV_ONEMEM_SIZE; us_MemIndex++ ){.
//			st_ResolConv_MemSet_Tbl[uc_MemSetNum][us_MemIndex].uc_Mem0 = Bicubic_Mem_NA_L[us_MemIndex];.
//			st_ResolConv_MemSet_Tbl[uc_MemSetNum][us_MemIndex].uc_Mem1 = Bicubic_Mem_NA_H[us_MemIndex];.
//			st_ResolConv_MemSet_Tbl[uc_MemSetNum][us_MemIndex].uc_Mem2 = Bicubic_Mem_NB_L[us_MemIndex];.
//			st_ResolConv_MemSet_Tbl[uc_MemSetNum][us_MemIndex].uc_Mem3 = Bicubic_Mem_NB_H[us_MemIndex];.
//			st_ResolConv_MemSet_Tbl[uc_MemSetNum][us_MemIndex].uc_Mem4 = Bicubic_Mem_NC_L[us_MemIndex];.
//			st_ResolConv_MemSet_Tbl[uc_MemSetNum][us_MemIndex].uc_Mem5 = Bicubic_Mem_NC_H[us_MemIndex];.
//			st_ResolConv_MemSet_Tbl[uc_MemSetNum][us_MemIndex].uc_Mem6 = Bicubic_Mem_ND_L[us_MemIndex];.
//			st_ResolConv_MemSet_Tbl[uc_MemSetNum][us_MemIndex].uc_Mem7 = Bicubic_Mem_ND_H[us_MemIndex];.
//		}.
//	}.
	return (uchar*)&st_ResolConv_MemSet_Tbl[0][0];
}

