// ================================================================================================.
//! <!--機能--> がたつき補正モードの取得.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param float sf_ResJaggyMode   ... 画像の解像度 (がたつき補正モード判定用) ※主走査、副走査の解像度が異なる場合は、解像度の小さい方.
//! <!--戻値-->.
//! \return   がたつき補正モード.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  09/10/27 三浦	新規作成(FAXがたつき補正IPROM対応).
//  09/12/14 三浦	CQ-323065 FAXがたつき補正IPROM仕様変更対応.
//  15/10/06 Sky	システム統合SoC(S800)対応.
//  17/04/07 Sky	ZeusSMLKPF対応.
// ================================================================================================.
THRE_JaggyCorrectMode THRC_S800IPRomPara_ImageConv::getJaggyCorrectMode( float sf_ResJaggyMode )
{
	THRE_JaggyCorrectMode e_JaggyCorrectMode = THRE_JaggyCorrectMode0;
	
		if( S800_ResSel[1] <= sf_ResJaggyMode ){
			// FAX受信画像の解像度が500dpi以上の場合は、モード0.
			e_JaggyCorrectMode = THRE_JaggyCorrectMode0;
		}else if( sf_ResJaggyMode < S800_ResSel[0] ){
			// FAX受信画像の解像度が300dpi未満の場合は、モード2.
			e_JaggyCorrectMode = THRE_JaggyCorrectMode2;
		}
		else{
			// FAX受信画像の解像度が300dpi以上、500dpi未満の場合は、モード1.
			e_JaggyCorrectMode = THRE_JaggyCorrectMode1;
	}
	
	return e_JaggyCorrectMode;
}

// 070820 tadamasa Donau Lab送信対応 IPROM追加 (S).

// ================================================================================================.
//! <!--機能--> TIFF-C 送信時白画像データを算出する.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param.
//! <!--戻値-->.
//! \return ul_InternalImage   ... 内部生成画像データ(8bit).
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  09/08/07 越野	 Donau環境から分離して作成.
//  17/04/07 Sky	 ZeusSMLKPF対応.
// ================================================================================================.
uint32_t THRC_S800IPRomPara_ImageConv::getInternalImageDataForSend( )
{
	uint32_t ul_InternalImage = 0;
	float fl_gainUpperA = 0.0f;
	float fl_gainLowerA = 0.0f;
	float fl_gainUpperB = 0.0f;
	float fl_gainLowerB = 0.0f;

	fl_gainLowerA = S800_TiffC_Send_DR[2];//上限値(A)のセット.
	fl_gainUpperA = S800_TiffC_Send_DR[3];//下限値(A)のセット.
	fl_gainLowerB = S800_TiffC_Send_DR[4];//上限値(B)のセット.
	fl_gainUpperB = S800_TiffC_Send_DR[5];//下限値(B)のセット.
	
	// 白データ(L).
	uint32_t ul_InternalImageL = 0x000000FF; 
	ul_InternalImage |= ul_InternalImageL; 
	// 白データ(A).
	uint32_t ul_InternalImageA = (uint32_t)(ceil((255*( 0 - fl_gainLowerA )) / ( fl_gainUpperA - fl_gainLowerA ))); 
	THRL_ThAssert( ul_InternalImageA < (1<<8), "THRC_S800IPRomPara_ImageConv::getInternalImageData(): ul_InternalImageA setting bit over!" , 0, 0, 0, 0, CFA14_DetailCode0x07B7 ); 
	ul_InternalImage |= ul_InternalImageA << 8; 
	// 白データ(B).
	uint32_t ul_InternalImageB = (uint32_t)(ceil((255*( 0 - fl_gainLowerB )) / ( fl_gainUpperB - fl_gainLowerB )));
	THRL_ThAssert( ul_InternalImageB < (1<<8), "THRC_S800IPRomPara_ImageConv::getInternalImageData(): ul_InternalImageB setting bit over!" , 0, 0, 0, 0, CFA14_DetailCode0x07B8 ); 
	ul_InternalImage |= ul_InternalImageB << 16; 
	
	return ul_InternalImage;
} 

//下地レベル対応 Start.
// ================================================================================================.
//! <!--機能--> 画像データ変換 シーケンス 下地レベル設定番号取得.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param THRE_LabMode e_mode ........Lab転送モード.
//! \param THRE_OriginalImageMode e_OriginalImgMode ........原稿画質.
//! \param TYPC_ImageAdjust c_ImgAdjust .................. 下地調整.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  09/08/07 越野	 Donau環境から分離して作成.
//  15/10/06 Sky	 システム統合SoC(S800)対応.
//  17/04/07 Sky	 ZeusSMLKPF対応.
// ================================================================================================.
unsigned char THRC_S800IPRomPara_ImageConv::getGroundingLvNo( THRE_LabMode e_mode, THRE_OriginalImageMode e_OriginalImgMode ,  TYPC_ImageAdjust& c_ImgAdjust )
{
	uchar uc_IndexFirst = chgModeToIndex(e_mode, e_OriginalImgMode);//一次元配列のIndexの補正.

	// HCL Warning Fix - Starts.
	// Warning No : 33569.
	THRL_ThAssert( uc_IndexFirst < 10 ,"getGroundingLvNo: uc_IndexFirst: %d Error ", uc_IndexFirst , 0, 0, 0, CFA14_DetailCode0x0CE4 ); 
	// HCL Warning Fix - Ends.

	uchar uc_IndexSecond = 0;
	if(c_ImgAdjust.getAutoExpo()==True){
		//自動の場合 固定値をセット.
		uc_IndexSecond = TYPE_BackDensityLevelN;
	}else{
		//下地調整のenumは4～-6の値を設定しているが、.
		//仕様では2～-6までの値しか使用しない為、補正を行う。.
		uchar uc_IndexBox[12] = {255,255,0,1,2,3,4,5,6,7,8,255};
		//マニュアルの場合.
		uchar uc_Index = (uchar)c_ImgAdjust.getBackDensity();//二次元配列のIndexの補正.
		//配列オーバーチェック.
		THRL_ThAssert(12 > uc_Index ,"getGroundingLvNo uc_IndexBox Err    %d", uc_Index , 0, 0, 0, CFA14_DetailCode0x07B9 ); 

		uc_IndexSecond = uc_IndexBox[uc_Index];
		//取得設定番号チェック.
		THRL_ThAssert(255 != uc_IndexSecond,"getGroundingLvNo Err Mode %d", uc_IndexSecond , 0, 0, 0, CFA14_DetailCode0x07BA ); 
	}
	return S800_No_AE[uc_IndexFirst][uc_IndexSecond];
}

// ================================================================================================.
//! <!--機能--> 画像データ変換 シーケンス テーブルNo補正　.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param THRE_LabMode e_mode ........Lab転送モード.
//! \param THRE_OriginalImageMode e_OriginalImgMode ........原稿画質.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  09/08/07 越野	 Donau環境から分離して作成.
//  15/10/06 Sky	 システム統合SoC(S800)対応.
//  17/04/07 Sky	 ZeusSMLKPF対応.
// ================================================================================================.
unsigned char THRC_S800IPRomPara_ImageConv::chgModeToIndex( THRE_LabMode e_mode, THRE_OriginalImageMode e_OriginalImgMode )
{
	//配列オーバーチェック.
	THRL_ThAssert(e_OriginalImgMode < 16,"chgModeToIndex e_OriginalImgMode Err  %d", e_OriginalImgMode , 0, 0, 0, CFA14_DetailCode0x07BB ); 

	unsigned char uc_Index = 0;
	uchar uc_ModeToIndexBox[16] = {255,0,1,2,3,4,5,6,7,7,7,7,7,7,255,255};
	
	//THRE_OriginalImageModeを配列の添え字にして、.
	//その添え字に応じた値を変数Indexにセットする。.
	switch(e_mode){
	case THRE_LabMode_RGB2Lab:
	case THRE_LabMode_RGB2Lab_Black:
		uc_Index = uc_ModeToIndexBox[e_OriginalImgMode];
		THRL_ThAssert(255 != uc_Index,"chgModeToIndex Err Mode %d", e_OriginalImgMode , 0, 0, 0, CFA14_DetailCode0x07BC ); 
		break;
	case THRE_LabMode_Lab2RGB:
	case THRE_LabMode_Lab2RGB_Black:
		//Lab受信時には原稿モードがないので固定をセットする。.
		uc_Index = 1;
		break;
	default:
		THRL_ThAssert(False,"chgModeToIndex Err e_mode %d", e_mode , 0, 0, 0, CFA14_DetailCode0x07BD ); 
		break;
	}
	return uc_Index;
}
