// ================================================================================================.
//! <!--機能--> 多値合成 フォ－ム側属性コ－ド設定レジスタ０、１の設定値を取得する.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param uchar uc_AttributeNum ........ 属性デ－タ数.
//! \param uchar uc_RegNo ............... レジスタインデックス.
//! \param uchar uc_TagSel .............. 文字色選択値 0:従来のオーバーレイの場合(default値).
//!                                                    1:コピーのオーバーレイで、色文字の場合.
//! <!--戻値-->.
//! \return レジスタ設定値.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  13/03/12 Sky		機種共通化対応.
//  15/10/06 Sky		システム統合SoC(S800)対応.
//  17/04/07 Sky		ZeusSMLKPF対応.
// ================================================================================================.
uint32_t THRC_S800IPRomPara_Synthesis::getFormTagCode( uchar uc_AttributeNum , uchar uc_RegNo , uchar uc_TagSel )
{
	uint32_t ul_FormTagCode = 0;
	uchar uc_Index = (uchar)(uc_RegNo * THRD_S800REG_ONEREG_SIZE);
	for( uchar i=0; i < THRD_S800REG_SETNUM_4BYTE; i++,uc_Index++ ){ 
		ul_FormTagCode |= p_FormTagCode[uc_TagSel][uc_Index] << (i * THRD_S800REG_SIFTNUM_8BIT);
	}
	return ul_FormTagCode;
}

