// ================================================================================================.
//! <!--機能--> 多値合成 明度(濃度)合成係数設定レジスタ0～4の設定値を取得する.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param uchar uc_RegNo ......................... レジスタインデックス.
//! <!--戻値-->.
//! \return レジスタ設定値.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  13/03/12 Sky		機種共通化対応.
//  15/10/06 Sky		システム統合SoC(S800)対応.
//  17/04/07 Sky		ZeusSMLKPF対応.
// ================================================================================================.
uint32_t THRC_S800IPRomPara_Synthesis::getBrigSynthesisCoeff( TYPE_ColorMode e_ColorMode, uchar uc_RegNo, uchar uc_DensityPercent )
{
	uint32_t ul_BrigSynthesisCoeff = 0;
	// フォ－ム側(sYCrCb)合成係数設定レジスタには、上位から設定された濃度を設定するようにする.
	// 明度(濃度)合成係数設定レジスタ1の場合、上位より渡された濃度(%単位)よりレジスタ値を算出する.
	// それ以外明度(濃度)合成係数設定レジスタ0,2～7は、IPROMより設定.

	if( uc_RegNo == 1 ){	// 明度(濃度)合成係数設定レジスタ1.
		uchar uc_DensityValue = (uchar)(_round( (uint32_t)(uc_DensityPercent*128), (uint32_t)100 ));
		for( uchar i=0; i < THRD_S800REG_SETNUM_3BYTE; i++ ){
			ul_BrigSynthesisCoeff |= uc_DensityValue << (i * THRD_S800REG_SIFTNUM_8BIT);
		}
	// オーバーレイYMCK強制付加対応 明度(濃度)合成係数設定レジスタ3(フォーム側YMCK)の場合.
	}else if( uc_RegNo == 3 ){	// 明度(濃度)合成係数設定レジスタ3.
		uchar uc_DensityValue = (uchar)(_round( (uint32_t)(uc_DensityPercent*128), (uint32_t)100 ));
		for( uchar i=0; i < THRD_S800REG_SETNUM_4BYTE; i++ ){		// YMCKだから4Byteに変更.
			ul_BrigSynthesisCoeff |= uc_DensityValue << (i * THRD_S800REG_SIFTNUM_8BIT);
		}
	}else{					// 明度(濃度)合成係数設定レジスタ0,2～7.
		for( uchar i=0; i < THRD_S800REG_SETNUM_4BYTE; i++ ){ 
			ul_BrigSynthesisCoeff |= p_BrigSynthesisCoeff[uc_RegNo][i] << (i * THRD_S800REG_SIFTNUM_8BIT);
		}
	}
	return ul_BrigSynthesisCoeff;
}

