// ================================================================================================.
//! <!--機能--> 多値合成 モノクロ用LOG変換テ－ブルデ－タの先頭アドレスを取得する.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param uchar uc_ModeSel ......................... 原稿側色モード 0:RGB, 1:YMCK.
//! \param なし.
//! <!--戻値-->.
//! \return LOG変換テ－ブルデ－タの先頭アドレス.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  13/03/12 Sky		機種共通化対応.
//  15/10/06 Sky		システム統合SoC(S800)対応.
