const uchar* THRC_S800IPRomPara_Synthesis::getMonoLogTableAddress( uchar uc_ModeSel )
{
	uchar* p = NULL;

	p = (uchar *)p_Mono_Log_Change_Tbl[ uc_ModeSel ];

	return p;
}


