// ================================================================================================.
//! <!--機能--> スレッド　画像データ変換 シーケンス CMMテーブル設定情報のポインタ取得.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param THRE_CtrID e_CtrID.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  09/08/07 陰山	Asic200から分岐.
//  13/07/12 Sky	THRC_AsicComAppInConvDivSeqから移動.
//  15/10/06 Sky	システム統合SoC(S800)対応.
// ================================================================================================.
THRS_CMMTblSetInfo_AppInConvDiv* THRC_S800IPRomPara_AppInConvDiv::getCMMTblSetInfo( THRE_CtrID e_CtrID )
{
	THRL_ThAssert( e_CtrID < THRE_CtrID_Num, "THRC_AsicComAppInConvDivSeq::getCMMTblSetInfo ArbiID %d", e_CtrID, 0, 0, 0, CFA14_DetailCode0x0984 );
	if( s_CMMTblSetInfo[ (uchar)e_CtrID ].vp_cmms_CMMRegSetData == NULL ){
		s_CMMTblSetInfo[ (uchar)e_CtrID ].vp_cmms_CMMRegSetData = (void*)(((uintptr_t)ThrImageConverterCtr_GetCMMS_CMMRegSetDataAppInConvDiv( e_CtrID ) + 0x7) & ~0x7 );
	}
	return &s_CMMTblSetInfo[ (uchar)e_CtrID ];
}

// ================================================================================================.
//! <!--機能--> スレッド　画像データ変換 シーケンス CMMテーブル設定情報の設定.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param THRS_CMMTblSetInfo_AppInConvDiv* ps_CMMTblSetInfo ... 【出力】CMMテーブル設定情報.
//! \param ST_ThreadComPara* ps_ThreadComPara ..... 【入力】スレッド共通パラメータ.
//! \param THRS_CMMInfo_AppInConvDiv* ps_CMMInfo       ..... 【入力】CMMInfo.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  09/08/07 陰山	Asic200から分岐.
//  11/09/12 戸田	Asic30用に画像補正有無フラグの追加.
//  13/07/12 Sky	THRC_AsicComAppInConvDivSeqから移動.
//  15/10/06 Sky	システム統合SoC(S800)対応.
// ================================================================================================.
void THRC_S800IPRomPara_AppInConvDiv::getCMMSetInfo( const THRS_CMMTblSetInfo_AppInConvDiv* ps_CMMTblSetInfo, uintptr_t ul_MsgPara, const ST_ThreadComPara* ps_ThreadComPara, THRS_CMMInfo_AppInConvDiv* ps_CMMInfo )
{
	THRS_MsgStartAppInConvDivProcIfArg* ps_MsgStartAppInConvDiv = (THRS_MsgStartAppInConvDivProcIfArg*)ul_MsgPara;
	THRS_S800_CMMS_CMMRegSetScreenData* ps_cmms_CMMRegSetData = (THRS_S800_CMMS_CMMRegSetScreenData*)(ps_CMMTblSetInfo->vp_cmms_CMMRegSetData);
	
	uchar uc_SetTblCnt = 0;
	// 色変換、又はモノカラ－有りの場合.
	if( True == ps_MsgStartAppInConvDiv->b_ColorConv ){
		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_00 ].ul_PciAdr = (uintptr_t)(&ps_cmms_CMMRegSetData->xcs_00[0]);
		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_00 ].ul_DataSize = XCS_00_SIZE_S800;			// メモリ0.
		ps_CMMInfo->e_CmmTblNo[ uc_SetTblCnt ] = THRE_CMMTblNo_XCS_00;
		uc_SetTblCnt++;

		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_01 ].ul_PciAdr = (uintptr_t)(&ps_cmms_CMMRegSetData->xcs_01[0]);
		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_01 ].ul_DataSize = XCS_01_SIZE_S800;			// メモリ1.
		ps_CMMInfo->e_CmmTblNo[ uc_SetTblCnt ] = THRE_CMMTblNo_XCS_01;
		uc_SetTblCnt++;
	}
	// 2値化有りの場合.
	if( True == ps_MsgStartAppInConvDiv->b_Binarize ){
		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_03 ].ul_PciAdr = (uintptr_t)(&ps_cmms_CMMRegSetData->xcs_03[0]);
		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_03 ].ul_DataSize = XCS_03_SIZE_S800;			// メモリ3.
		ps_CMMInfo->e_CmmTblNo[ uc_SetTblCnt ] = THRE_CMMTblNo_XCS_03;
		uc_SetTblCnt++;

		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_04 ].ul_PciAdr = (uintptr_t)(&ps_cmms_CMMRegSetData->xcs_04[0]);
		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_04 ].ul_DataSize = XCS_SCREEN_SIZE_S800;			// メモリ4.
		ps_CMMInfo->e_CmmTblNo[ uc_SetTblCnt ] = THRE_CMMTblNo_XCS_04;
		uc_SetTblCnt++;

		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_05 ].ul_PciAdr = (uintptr_t)(&ps_cmms_CMMRegSetData->xcs_05[0]);
		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_05 ].ul_DataSize = XCS_SCREEN_SIZE_S800;			// メモリ5.
		ps_CMMInfo->e_CmmTblNo[ uc_SetTblCnt ] = THRE_CMMTblNo_XCS_05;
		uc_SetTblCnt++;

		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_06 ].ul_PciAdr = (uintptr_t)(&ps_cmms_CMMRegSetData->xcs_06[0]);
		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_06 ].ul_DataSize = XCS_SCREEN_SIZE_S800;			// メモリ6.
		ps_CMMInfo->e_CmmTblNo[ uc_SetTblCnt ] = THRE_CMMTblNo_XCS_06;
		uc_SetTblCnt++;

		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_07 ].ul_PciAdr = (uintptr_t)(&ps_cmms_CMMRegSetData->xcs_07[0]);
		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_07 ].ul_DataSize = XCS_SCREEN_SIZE_S800;			// メモリ7.
		ps_CMMInfo->e_CmmTblNo[ uc_SetTblCnt ] = THRE_CMMTblNo_XCS_07;
		uc_SetTblCnt++;

		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_08 ].ul_PciAdr = (uintptr_t)(&ps_cmms_CMMRegSetData->xcs_08[0]);
		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_08 ].ul_DataSize = XCS_SCREEN_SIZE_S800;			// メモリ8.
		ps_CMMInfo->e_CmmTblNo[ uc_SetTblCnt ] = THRE_CMMTblNo_XCS_08;
		uc_SetTblCnt++;

		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_09 ].ul_PciAdr = (uintptr_t)(&ps_cmms_CMMRegSetData->xcs_09[0]);
		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_09 ].ul_DataSize = XCS_SCREEN_SIZE_S800;			// メモリ9.
		ps_CMMInfo->e_CmmTblNo[ uc_SetTblCnt ] = THRE_CMMTblNo_XCS_09;
		uc_SetTblCnt++;

		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_10 ].ul_PciAdr = (uintptr_t)(&ps_cmms_CMMRegSetData->xcs_10[0]);
		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_10 ].ul_DataSize = XCS_SCREEN_SIZE_S800;			// メモリ10.
		ps_CMMInfo->e_CmmTblNo[ uc_SetTblCnt ] = THRE_CMMTblNo_XCS_10;
		uc_SetTblCnt++;

		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_11 ].ul_PciAdr = (uintptr_t)(&ps_cmms_CMMRegSetData->xcs_11[0]);
		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_11 ].ul_DataSize = XCS_SCREEN_SIZE_S800;			// メモリ11.
		ps_CMMInfo->e_CmmTblNo[ uc_SetTblCnt ] = THRE_CMMTblNo_XCS_11;
		uc_SetTblCnt++;

		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_12 ].ul_PciAdr = (uintptr_t)(&ps_cmms_CMMRegSetData->xcs_12[0]);
		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_12 ].ul_DataSize = XCS_SCREEN_SIZE_S800;			// メモリ12.
		ps_CMMInfo->e_CmmTblNo[ uc_SetTblCnt ] = THRE_CMMTblNo_XCS_12;
		uc_SetTblCnt++;

		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_13 ].ul_PciAdr = (uintptr_t)(&ps_cmms_CMMRegSetData->xcs_13[0]);
		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_13 ].ul_DataSize = XCS_SCREEN_SIZE_S800;			// メモリ13.
		ps_CMMInfo->e_CmmTblNo[ uc_SetTblCnt ] = THRE_CMMTblNo_XCS_13;
		uc_SetTblCnt++;

		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_14 ].ul_PciAdr = (uintptr_t)(&ps_cmms_CMMRegSetData->xcs_14[0]);
		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_14 ].ul_DataSize = XCS_SCREEN_SIZE_S800;			// メモリ14.
		ps_CMMInfo->e_CmmTblNo[ uc_SetTblCnt ] = THRE_CMMTblNo_XCS_14;
		uc_SetTblCnt++;

		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_15 ].ul_PciAdr = (uintptr_t)(&ps_cmms_CMMRegSetData->xcs_15[0]);
		ps_CMMInfo->s_RWInfo[ THRE_CMMTblNo_XCS_15 ].ul_DataSize = XCS_SCREEN_SIZE_S800;			// メモリ15.
		ps_CMMInfo->e_CmmTblNo[ uc_SetTblCnt ] = THRE_CMMTblNo_XCS_15;
		uc_SetTblCnt++;
	}
	// 転送したいテ－ブル数を設定する.
	ps_CMMInfo->uc_SetCMMTblCnt = uc_SetTblCnt;
}

// ================================================================================================.
//! <!--機能--> CMMパラメータ設定.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \paramTHRS_CMMTblSetInfo* ps_CmmTblSetInfo  CMMテーブル情報.
//! \param THRS_MsgStartAppInConvDivProcIfArg* ps_MsgStartImageConv  Msgパラメータ.
//! \param ST_ThreadComPara* ps_ThreadComPara  スレッドパラメータ.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  13/03/26 Sky	ZeusS対応 THRC_AsicComAppInConvDivSeqクラスから移動.
//  15/10/06 Sky	システム統合SoC(S800)対応.
// ================================================================================================.
void THRC_S800IPRomPara_AppInConvDiv::setCMMSRAMRW( THRS_CMMTblSetInfo_AppInConvDiv* ps_CMMTblSetInfo, uintptr_t ul_MsgPara, ST_ThreadComPara* ps_ThreadComPara, IMGC_Image* pc_Image )
{
	THRS_MsgStartAppInConvDivProcIfArg* ps_MsgStartImageConv = (THRS_MsgStartAppInConvDivProcIfArg*)ul_MsgPara;
	THRS_S800_CMMS_CMMRegSetScreenData* ps_cmms_CMMRegSetData = (THRS_S800_CMMS_CMMRegSetScreenData*)(ps_CMMTblSetInfo->vp_cmms_CMMRegSetData);

	// 画像補正(原稿モード)モードの取得.
	THRE_AsicComMSMode e_MSMode = getMSMode( ps_MsgStartImageConv->s_BufImgInfo.e_ImageColor, ps_MsgStartImageConv->b_1200Mode, ps_ThreadComPara->c_ThreadIF.c_PrinterImageAdjust.getOriginalImageType() );

	// 色変換有りの場合、テ－ブルを設定する.
	if( True == ps_MsgStartImageConv->b_ColorConv ){
		if ( True == ps_MsgStartImageConv->b_1200Mode ) { // 600dpiはTHRE_AsicComModeMSMode_Throughを許可する.
			THRL_ThAssert( e_MSMode != THRE_AsicComModeMSMode_Through, "THRC_AsicComAppInConvDivSeq::setCMMSRAMRW(): illegal MSMode parameter.", 0, 0, 0, 0, CFA14_DetailCode0x0970 );
		}
		memset( &ps_cmms_CMMRegSetData->xcs_00[0], 0, XCS_00_SIZE_S800 );
		getIPTableAddress( &ps_cmms_CMMRegSetData->xcs_00[0], THRE_CMMTblNo_XCS_00, e_MSMode, ps_ThreadComPara, b_4DimensionConv, pc_Image );

		memset( &ps_cmms_CMMRegSetData->xcs_01[0], 0, XCS_01_SIZE_S800 );
		getIPTableAddress( &ps_cmms_CMMRegSetData->xcs_01[0], THRE_CMMTblNo_XCS_01, e_MSMode, ps_ThreadComPara, b_4DimensionConv, pc_Image );
	}

	// 2値化有りの場合、テ－ブルを設定する.
	if( True == ps_MsgStartImageConv->b_Binarize ){
		THRL_ThAssert( e_MSMode != THRE_AsicComModeMSMode_Through, "THRC_AsicComAppInConvDivSeq::setCMMSRAMRW(): illegal CMMmode parameter.", 0, 0, 0, 0, CFA14_DetailCode0x0975 );
		getIPTableAddress( &ps_cmms_CMMRegSetData->xcs_03[0], THRE_CMMTblNo_XCS_03, e_MSMode, ps_ThreadComPara, b_4DimensionConv, pc_Image );
		getIPTableAddress( &ps_cmms_CMMRegSetData->xcs_04[0], THRE_CMMTblNo_XCS_04, e_MSMode, ps_ThreadComPara, b_4DimensionConv, pc_Image );
		getIPTableAddress( &ps_cmms_CMMRegSetData->xcs_05[0], THRE_CMMTblNo_XCS_05, e_MSMode, ps_ThreadComPara, b_4DimensionConv, pc_Image );
		getIPTableAddress( &ps_cmms_CMMRegSetData->xcs_06[0], THRE_CMMTblNo_XCS_06, e_MSMode, ps_ThreadComPara, b_4DimensionConv, pc_Image );
		getIPTableAddress( &ps_cmms_CMMRegSetData->xcs_07[0], THRE_CMMTblNo_XCS_07, e_MSMode, ps_ThreadComPara, b_4DimensionConv, pc_Image );
		getIPTableAddress( &ps_cmms_CMMRegSetData->xcs_08[0], THRE_CMMTblNo_XCS_08, e_MSMode, ps_ThreadComPara, b_4DimensionConv, pc_Image );
		getIPTableAddress( &ps_cmms_CMMRegSetData->xcs_09[0], THRE_CMMTblNo_XCS_09, e_MSMode, ps_ThreadComPara, b_4DimensionConv, pc_Image );
		getIPTableAddress( &ps_cmms_CMMRegSetData->xcs_10[0], THRE_CMMTblNo_XCS_10, e_MSMode, ps_ThreadComPara, b_4DimensionConv, pc_Image );
		getIPTableAddress( &ps_cmms_CMMRegSetData->xcs_11[0], THRE_CMMTblNo_XCS_11, e_MSMode, ps_ThreadComPara, b_4DimensionConv, pc_Image );
		getIPTableAddress( &ps_cmms_CMMRegSetData->xcs_12[0], THRE_CMMTblNo_XCS_12, e_MSMode, ps_ThreadComPara, b_4DimensionConv, pc_Image );
		getIPTableAddress( &ps_cmms_CMMRegSetData->xcs_13[0], THRE_CMMTblNo_XCS_13, e_MSMode, ps_ThreadComPara, b_4DimensionConv, pc_Image );
		getIPTableAddress( &ps_cmms_CMMRegSetData->xcs_14[0], THRE_CMMTblNo_XCS_14, e_MSMode, ps_ThreadComPara, b_4DimensionConv, pc_Image );
		getIPTableAddress( &ps_cmms_CMMRegSetData->xcs_15[0], THRE_CMMTblNo_XCS_15, e_MSMode, ps_ThreadComPara, b_4DimensionConv, pc_Image );
	}
}

// ================================================================================================.
//! <!--機能--> CMM_レジスタテ－ブル取得＆設定.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param THRS_MsgStartAppInConvDivProcIfArg* ps_MsgStartImageConv  Msgパラメータ.
//! \param ST_ThreadComPara* ps_ThreadComPara  スレッドパラメータ.
//! \param TYPE_ColorMode e_ColorMode			カラーモード.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  13/03/26 Sky	ZeusS対応 THRC_AsicComAppInConvDivSeqクラスから移動.
//  13/07/12 Sky	ZeusS対応 THRC_AsicComIPRomPara_AppInConvDivから移動.
//                            IPRom分離対応.
//  15/10/06 Sky	システム統合SoC(S800)対応.
//  18/07/20 Sky	KRQ-361 EagleSparrowの画質改善の件 (PCLの1200dpiのプリント).
// ================================================================================================.
void THRC_S800IPRomPara_AppInConvDiv::setCmmRegTable( uintptr_t ul_Param, ST_ThreadComPara* ps_ThreadComPara, TYPE_ColorMode e_ColorMode  ) // yamashita iprom add.
{
	THRS_MsgStartAppInConvDivProcIfArg* ps_MsgStartImageConv = (THRS_MsgStartAppInConvDivProcIfArg*)ul_Param;
	memset( &ps_IPRomPara->s_CMMReg, 0, sizeof(THRS_CMMReg_AppInConvDiv));
	
	// CMMモードの取得.
	THRE_AsicComCmmMode e_CmmMode = getCmmMode( ps_MsgStartImageConv->s_BufImgInfo.e_ImageColor, ps_MsgStartImageConv->e_DstImageColor,
		ps_MsgStartImageConv->b_1200Mode, b_4DimensionConv );

	if( b_debug_ct_log == True || us_Debug_AppInConvDiv_IpRomMode > 0 ){
		THRL_SetThLog( 494, THRE_DebugLogType_CTLog, 0, False, e_CmmMode );
	}

	int32_t i = 0;

	// 画像補正(原稿モード)モードの取得.
	THRE_AsicComMSMode e_MSMode = getMSMode( ps_MsgStartImageConv->s_BufImgInfo.e_ImageColor, ps_MsgStartImageConv->b_1200Mode,
		ps_ThreadComPara->c_ThreadIF.c_PrinterImageAdjust.getOriginalImageType() );

	// CMYK　色変換ﾏﾄﾘｸｽ係数設定レジスタの設定値を取得する.
	uchar uc_Cnt1 = 0;
	uchar uc_Cnt2 = 0;
	uchar uc_Cnt3 = 0;
	ushort us_MatrixAns[3][3] = {{0,0,0},{0,0,0},{0,0,0}};	// 演算結果格納用.
	IMGC_Image* pc_Image = ps_ThreadComPara->c_ThreadIF.pc_Leaf->getImage();
	for( uc_Cnt1 = 0; uc_Cnt1 < THRE_ASICCOM_BANKINDEX_MAX; uc_Cnt1++ ){	// Bank0～2.
		getColorMatrix( e_MSMode, ps_ThreadComPara, b_4DimensionConv, uc_Cnt1, us_MatrixAns, e_ColorMode, pc_Image );
		for( uc_Cnt2 = 0; uc_Cnt2 < THRE_ASICCOM_REGINDEX_6; uc_Cnt2++ ){	// RegNo.(1Bank分)分繰り返す.
			ps_IPRomPara->s_CMMReg.ul_ColorMatrix[ uc_Cnt3 ] = getColorMatrix_Reg( uc_Cnt2, us_MatrixAns );
			uc_Cnt3++;
		}
		// 1Bank分ログ出力(ログの第5パラメータがshort型なので2つに分ける).
		THRL_SetThLog( 687, THRE_DebugLogType_CTLog, 0, False, uc_Cnt1
			, ps_IPRomPara->s_CMMReg.ul_ColorMatrix[(uc_Cnt1*THRE_ASICCOM_REGINDEX_6)+THRE_ASICCOM_REGINDEX_0]
			, ps_IPRomPara->s_CMMReg.ul_ColorMatrix[(uc_Cnt1*THRE_ASICCOM_REGINDEX_6)+THRE_ASICCOM_REGINDEX_1]
			, ps_IPRomPara->s_CMMReg.ul_ColorMatrix[(uc_Cnt1*THRE_ASICCOM_REGINDEX_6)+THRE_ASICCOM_REGINDEX_2] );
		THRL_SetThLog( 688, THRE_DebugLogType_CTLog, 0, False, uc_Cnt1
			, ps_IPRomPara->s_CMMReg.ul_ColorMatrix[(uc_Cnt1*THRE_ASICCOM_REGINDEX_6)+THRE_ASICCOM_REGINDEX_3]
			, ps_IPRomPara->s_CMMReg.ul_ColorMatrix[(uc_Cnt1*THRE_ASICCOM_REGINDEX_6)+THRE_ASICCOM_REGINDEX_4]
			, ps_IPRomPara->s_CMMReg.ul_ColorMatrix[(uc_Cnt1*THRE_ASICCOM_REGINDEX_6)+THRE_ASICCOM_REGINDEX_5] );
	}

	// CMYK　TAG変換値設定レジスタの設定値を取得する.
	ps_IPRomPara->s_CMMReg.ul_TagSetting		= getTagSetting( e_CmmMode );
	
	// CMYK　γ補正ﾃｰﾌﾞﾙ選択設定レジスタの設定値を取得する.
	ps_IPRomPara->s_CMMReg.ul_GammaTable		= getGammaTable( e_CmmMode );
	
	// CMYK　4次元LUT用設定レジスタの設定値を取得する.
	ps_IPRomPara->s_CMMReg.ul_4DimensionLUT	= get4DimensionLUT( e_CmmMode );
	
	// CMYK　白色格子点の置換ﾃﾞｰﾀ設定レジスタの設定値を取得する.
	for( i = 0; i < int32_t(sizeof(ps_IPRomPara->s_CMMReg.ul_WhiteChange)/sizeof(ps_IPRomPara->s_CMMReg.ul_WhiteChange[0])); i++ ){
		ps_IPRomPara->s_CMMReg.ul_WhiteChange[i]	= getWhiteChange( e_CmmMode, (THRE_AsicComIPParam_Kind)i );
	}
	
	// CMYK　ﾘｱﾙﾀｲﾑ補間ｽﾙｰ判定用REFﾃﾞｰﾀ設定レジスタの設定値を取得する.
	ps_IPRomPara->s_CMMReg.ul_ThroughREF		= getThroughREF( e_CmmMode );
	
	// CMYK　明度作成用R,G,B比ﾃﾞｰﾀ設定レジスタの設定値を取得する.
	for( i = 0; i < int32_t(sizeof(ps_IPRomPara->s_CMMReg.ul_BrigRatio)/sizeof(ps_IPRomPara->s_CMMReg.ul_BrigRatio[0])); i++ ){
		ps_IPRomPara->s_CMMReg.ul_BrigRatio[i]	= getBrigRatio( e_CmmMode );
	}
	
	// CMYK　ﾓﾉｶﾗｰ用Y,M,C,Kﾃﾞｰﾀ変調ﾃﾞｰﾀ設定レジスタの設定値を取得する.
	for( i = 0; i < int32_t(sizeof(ps_IPRomPara->s_CMMReg.ul_MonoCoeff)/sizeof(ps_IPRomPara->s_CMMReg.ul_MonoCoeff[0])); i++ ){
		ps_IPRomPara->s_CMMReg.ul_MonoCoeff[i]	= getMonoCoeff( e_CmmMode, (THRE_AsicComIPParam_Kind)i );
	}
	
	// CMYK　ﾓﾉｶﾗｰ・ﾌﾙｶﾗｰ用ﾃﾞｰﾀ選択信号設定レジスタの設定値を取得する.
	ps_IPRomPara->s_CMMReg.ul_MonoFullSelSig	= getMonoFullSelSig( e_CmmMode );
	
	// CMYK　ﾓﾉｶﾗｰ・2ｶﾗｰ用ﾃﾞｰﾀ選択信号設定レジスタの設定値を取得する.
	ps_IPRomPara->s_CMMReg.ul_Mono2ColSelSig	= getMono2ColSelSig( e_CmmMode );
	
	// CMYK　領域外の論理置換値設定レジスタの設定値を取得する.
	ps_IPRomPara->s_CMMReg.ul_LogChg			= getLogChg( e_CmmMode );
	
	// CMYK　黒置換許可設定レジスタの設定値を取得する.
	ps_IPRomPara->s_CMMReg.ul_BlackChg			= getBlackChg( e_CmmMode );
	
	// CMYK　ﾃﾞｰﾀﾊﾞｽ選択設定レジスタの設定値を取得する.
	ps_IPRomPara->s_CMMReg.ul_DataBus 		= getDataBus( e_CmmMode );
	
	// CMYK　ﾌﾙｶﾗｰ/ﾓﾉｸﾛ選択設定レジスタの設定値を取得する.
	ps_IPRomPara->s_CMMReg.ul_MonoFullSel		= getMonoFullSel( e_CmmMode );
	
	// CMYK　K単色変換設定レジスタの設定値を取得する.
	ps_IPRomPara->s_CMMReg.ul_KMonoChg		= getKMonoChg( e_CmmMode );
	
	// CMYK　ﾄﾅｰｾｰﾌﾞ基準関連レジスタの設定値を取得する.
	for( i = 0; i < int32_t(sizeof(ps_IPRomPara->s_CMMReg.ul_TonerSave)/sizeof(ps_IPRomPara->s_CMMReg.ul_TonerSave[0])); i++ ){
		if( i < 3 ){
			// CMYK　ﾄﾅｰｾｰﾌﾞ基準ﾃﾞｰﾀ生成係数設定レジスタの設定値を取得する.
			ps_IPRomPara->s_CMMReg.ul_TonerSave[i]	= getTonerSaveBaseCreate( e_CmmMode, (uchar)i );
		}else if( (i >= 3) && (i < 6) ){
			// CMYK　ﾄﾅｰｾｰﾌﾞ基準合成係数設定レジスタの設定値を取得する.
			ps_IPRomPara->s_CMMReg.ul_TonerSave[i]	= getTonerSaveBaseComp( e_CmmMode, (uchar)(i-3) );
		}else if( i == 6 ){
			// CMYK　ﾄﾅｰｾｰﾌﾞﾃﾞｰﾀ算出ﾘﾌｧﾚﾝｽ係数設定レジスタの設定値を取得する.
			ps_IPRomPara->s_CMMReg.ul_TonerSave[i]	= getTonerSaveCalcRef( e_CmmMode );
		}else if( (i >= 7) && (i < 10) ){
			// CMYK　ﾄﾅｰｾｰﾌﾞﾃﾞｰﾀ生成係数設定レジスタの設定値を取得する.
			ps_IPRomPara->s_CMMReg.ul_TonerSave[i]	= getTonerSaveCreate( e_CmmMode, (uchar)(i-7) );
		}else{
			// CMYK　ﾄﾅｰｾｰﾌﾞ許可/禁止設定レジスタの設定値を取得する.
			ps_IPRomPara->s_CMMReg.ul_TonerSave[i]	= getTonerSaveEnable( e_CmmMode );
		}
	}
	
	// CMYK　付着量制限処理レジスタの設定値を取得する.
	for( i = 0; i < int32_t(sizeof(ps_IPRomPara->s_CMMReg.ul_QuantLimit)/sizeof(ps_IPRomPara->s_CMMReg.ul_QuantLimit[0])); i++ ){
		if( i == 0 ){
			// CMYK　付着量制限処理1段目　最大付着量設定レジスタの設定値を取得する.
			ps_IPRomPara->s_CMMReg.ul_QuantLimit[i]	= getQuantLimit1stMax( e_CmmMode );
		}else if( i == 1 ){
			// CMYK　付着量制限処理許可/禁止設定レジスタの設定値を取得する.
			ps_IPRomPara->s_CMMReg.ul_QuantLimit[i]	= getQuantLimitEnable( e_CmmMode );
		}else if( i == 2 ){
			// CMYK　付着量制限処理1段目　最大付着量ゲイン係数設定レジスタの設定値を取得する.
			ps_IPRomPara->s_CMMReg.ul_QuantLimit[i]	= getQuantLimit1stMaxGain( e_CmmMode );
		}else if( i == 3 ){
			// CMYK　付着量制限処理2段目　最大付着量設定レジスタの設定値を取得する.
			ps_IPRomPara->s_CMMReg.ul_QuantLimit[i]	= getQuantLimit2ndMax( e_CmmMode );
		}
	}
	
	// CMYK　モノクロ変換TBLアドレス選択設定レジスタの設定値を取得する.
	ps_IPRomPara->s_CMMReg.ul_MonoTBL		= getMonoTBL( e_CmmMode );
	
	// CMYK　K乗算係数設定レジスタの設定値を取得する.
	ps_IPRomPara->s_CMMReg.ul_KCoeff			= getKCoeff( e_CmmMode );
	
	// CMYK　色シャッフル選択設定レジスタの設定値を取得する.
	ps_IPRomPara->s_CMMReg.ul_ColShuff		= getColShuff( e_CmmMode );
	
	// CMYK　TAGコード変換信号設定レジスタの設定値を取得する.
	ps_IPRomPara->s_CMMReg.ul_TAGCodeChg		= getTAGCodeChg( e_CmmMode );
	
	// CMYK　領域外置換データ設定レジスタの設定値を取得する.
	ps_IPRomPara->s_CMMReg.ul_ChgData		= getChgData( e_CmmMode );
	
	// CMYK　ネガポジ反転選択レジスタの設定値を取得する.
	ps_IPRomPara->s_CMMReg.ul_NegaPosiSwitch	= getNegaPosiSwitch();
}

// ================================================================================================.
//! <!--機能--> IPテーブルアドレス取得.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param uchar* p_TableDataSetAddr .................. テーブルデータ設定先アドレス.
//! \param THRE_CMMTblNo_AppInConvDiv uc_XcsIndex .............. XCSの配列番号.
//! \param THRE_AsicComMSMode e_Mode ................... 画像補正モード(原稿モード).
//! \param const ST_ThreadComPara* ps_ThreadComPara ... マルチスレッド 画像転送開始メッセージパラメータ.
//! \param Bool b_4DimensionConv ...................... 4次元⇒4次元変換フラグ.
//! \param const IMGC_Image* pc_Image ................. 入力イメージ情報.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  11/02/09 大石		Asic30対応新規作成.
//  11/05/20 大石		問題点No.176(CQ:346013)対応 COSIM検証No.2012のAsic30_xcs_00、Asic30_xcs_01のIndex番号を修正.
//  12/03/05 鋤柄		IPROM機種カスタマイズ対応.
//  12/05/28 山下		CT問題点修正 問題点№21 グレイの場合のテーブル選択を修正.
//  12/06/06 山下		IPROM機種カスタマイズ対応(ガンマ補正対応) getMemoryMapTBL3の引数にST_ThreadComPara追加.
//  12/06/14 世古		getImage関数のコール数削減対応.
//  13/03/12 Sky		ZeusS対応 DMA29用のIPROM処理(Asic30からコピー).
//  15/10/06 Sky		システム統合SoC(S800)対応.
// ================================================================================================.
void THRC_S800IPRomPara_AppInConvDiv::getIPTableAddress( uchar* p_TableDataSetAddr, THRE_CMMTblNo_AppInConvDiv e_XcsIndex, THRE_AsicComMSMode e_MSMode, const ST_ThreadComPara* ps_ThreadComPara, Bool b_4DimensionConv, const IMGC_Image* pc_Image )
{
	switch ( e_XcsIndex ) {
		case THRE_CMMTblNo_XCS_00:
			getMemoryMapTBL0( p_TableDataSetAddr, e_MSMode, ps_ThreadComPara, b_4DimensionConv, pc_Image );			// DMA19 色変換用メモリマップテーブル０.
			break;
		case THRE_CMMTblNo_XCS_01:
			getMemoryMapTBL1( p_TableDataSetAddr, e_MSMode, ps_ThreadComPara, b_4DimensionConv, pc_Image );			// DMA19 色変換用メモリマップテーブル１.
			break;
		case THRE_CMMTblNo_XCS_03:
			getMemoryMapTBL3( p_TableDataSetAddr, e_MSMode, ps_ThreadComPara, pc_Image );							// DMA19 スクリーン処理用メモリマップ３.
			break;
		case THRE_CMMTblNo_XCS_04:																					// DMA19 スクリーン処理部メモリマップ４.
			getScreenMapTBL_Mtrx( p_TableDataSetAddr, e_MSMode, ps_ThreadComPara, THRE_AsicComYMCKColorKind_Y, THRE_AsicComIPParam_Kind_0, pc_Image );
			break;
		case THRE_CMMTblNo_XCS_05:																					// DMA19 スクリーン処理部メモリマップ５.
			getScreenMapTBL_Mtrx( p_TableDataSetAddr, e_MSMode, ps_ThreadComPara, THRE_AsicComYMCKColorKind_Y, THRE_AsicComIPParam_Kind_1, pc_Image );
			break;
		case THRE_CMMTblNo_XCS_06:																					// DMA19 スクリーン処理部メモリマップ６.
			getScreenMapTBL_Mtrx( p_TableDataSetAddr, e_MSMode, ps_ThreadComPara, THRE_AsicComYMCKColorKind_Y, THRE_AsicComIPParam_Kind_2, pc_Image );
			break;
		case THRE_CMMTblNo_XCS_07:																					// DMA19 スクリーン処理部メモリマップ７.
			getScreenMapTBL_Mtrx( p_TableDataSetAddr, e_MSMode, ps_ThreadComPara, THRE_AsicComYMCKColorKind_M, THRE_AsicComIPParam_Kind_0, pc_Image );
			break;
		case THRE_CMMTblNo_XCS_08:																					// DMA19 スクリーン処理部メモリマップ８.
			getScreenMapTBL_Mtrx( p_TableDataSetAddr, e_MSMode, ps_ThreadComPara, THRE_AsicComYMCKColorKind_M, THRE_AsicComIPParam_Kind_1, pc_Image );
			break;
		case THRE_CMMTblNo_XCS_09:																					// DMA19 スクリーン処理部メモリマップ９.
			getScreenMapTBL_Mtrx( p_TableDataSetAddr, e_MSMode, ps_ThreadComPara, THRE_AsicComYMCKColorKind_M, THRE_AsicComIPParam_Kind_2, pc_Image );
			break;
		case THRE_CMMTblNo_XCS_10:																					// DMA19 スクリーン処理部メモリマップ１０.
			getScreenMapTBL_Mtrx( p_TableDataSetAddr, e_MSMode, ps_ThreadComPara, THRE_AsicComYMCKColorKind_C, THRE_AsicComIPParam_Kind_0, pc_Image );
			break;
		case THRE_CMMTblNo_XCS_11:																					// DMA19 スクリーン処理部メモリマップ１１.
			getScreenMapTBL_Mtrx( p_TableDataSetAddr, e_MSMode, ps_ThreadComPara, THRE_AsicComYMCKColorKind_C, THRE_AsicComIPParam_Kind_1, pc_Image );
			break;
		case THRE_CMMTblNo_XCS_12:																					// DMA19 スクリーン処理部メモリマップ１２.
			getScreenMapTBL_Mtrx( p_TableDataSetAddr, e_MSMode, ps_ThreadComPara, THRE_AsicComYMCKColorKind_C, THRE_AsicComIPParam_Kind_2, pc_Image );
			break;
		case THRE_CMMTblNo_XCS_13:																					// DMA19 スクリーン処理部メモリマップ１３.
			getScreenMapTBL_Mtrx( p_TableDataSetAddr, e_MSMode, ps_ThreadComPara, THRE_AsicComYMCKColorKind_K, THRE_AsicComIPParam_Kind_0, pc_Image );
			break;
		case THRE_CMMTblNo_XCS_14:																					// DMA19 スクリーン処理部メモリマップ１４.
			getScreenMapTBL_Mtrx( p_TableDataSetAddr, e_MSMode, ps_ThreadComPara, THRE_AsicComYMCKColorKind_K, THRE_AsicComIPParam_Kind_1, pc_Image );
			break;
		case THRE_CMMTblNo_XCS_15:																					// DMA19 スクリーン処理部メモリマップ１５.
			getScreenMapTBL_Mtrx( p_TableDataSetAddr, e_MSMode, ps_ThreadComPara, THRE_AsicComYMCKColorKind_K, THRE_AsicComIPParam_Kind_2, pc_Image );
			break;
		default:
			THRL_ThAssert( False, "THRC_S800IPRomPara_AppInConvDiv::getIPTableAddress e_XcsIndex err %d", e_XcsIndex ,0 ,0 ,0 ,CFA14_DetailCode0x0C47 );
			break;
	}

	return;
}

// ================================================================================================.
//! <!--機能--> スクリーン処理_レジスタテ－ブル取得＆設定.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param THRS_MsgStartAppInConvDivProcIfArg* ps_MsgStartImageConv  Msgパラメータ.
//! \param ST_ThreadComPara* ps_ThreadComPara  スレッドパラメータ.
//! \param TYPE_ColorMode e_ColorMode			カラーモード.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  13/03/26 Sky	ZeusS対応 THRC_AsicComAppInConvDivSeqクラスから移動.
//  13/07/12 Sky	ZeusS対応 THRC_AsicComIPRomPara_AppInConvDivクラスから移動.
//  14/06/22 Sky    IPROM(スクリーン)対応
//  15/10/06 Sky	システム統合SoC(S800)対応.
//  17/04/07 Sky	ZeusSMLKPF対応.
// ================================================================================================.
void THRC_S800IPRomPara_AppInConvDiv::setBinalizerRegTable( uintptr_t ul_Param, ST_ThreadComPara* ps_ThreadComPara, TYPE_ColorMode e_ColorMode  ) // yamashita iprom add.
{
	THRS_MsgStartAppInConvDivProcIfArg* ps_MsgStartImageConv = (THRS_MsgStartAppInConvDivProcIfArg*)ul_Param;

	memset( &ps_IPRomPara->s_BinarizerReg, 0, sizeof(THRS_BinarizerReg_AppInConvDiv));

	// ｽｸﾘｰﾝﾓｰﾄﾞの取得.
	THRE_AsicComScreenMode e_ScreenMode = getScreenMode( ps_MsgStartImageConv->b_1200Mode );

	if( b_debug_ct_log == True || us_Debug_AppInConvDiv_IpRomMode > 0 ){
		THRL_SetThLog( 496, THRE_DebugLogType_CTLog, 0, False, e_ScreenMode );
	}

	// 画像補正(原稿モード)モードの取得.
	THRE_AsicComMSMode e_MSMode = getMSMode( ps_MsgStartImageConv->s_BufImgInfo.e_ImageColor, ps_MsgStartImageConv->b_1200Mode,
		ps_ThreadComPara->c_ThreadIF.c_PrinterImageAdjust.getOriginalImageType() );

	int32_t i = 0;
	ushort us_ScreenCol_Mode = 0;
	IMGC_Image* pc_Image = ps_ThreadComPara->c_ThreadIF.pc_Leaf->getImage();
	THRL_ThAssert( pc_Image != NULL, "THRC_AsicComAppInConvDivSeq::setBinalizerRegTable pc_Image is NULL.", 0, 0, 0, 0, CFA14_DetailCode0x0A95 );

	if( TYPE_ColorModeFullColor == e_ColorMode ){
	  us_ScreenCol_Mode = us_AsicComIPParam_MselScreenDA_Col;
	}else{
	  us_ScreenCol_Mode = us_AsicComIPParam_MselScreenDA_Bk;
	}


	for( i =0; i < THRE_AsicComYMCKColorKind_Max; i++ ){
		// ｽｸﾘｰﾝ処理　γ補正ﾃｰﾌﾞﾙ 設定レジスタの設定値を取得する.
		ps_IPRomPara->s_BinarizerReg.ul_GammaTable[i]	= getGammaScreenTable( e_ScreenMode, (THRE_AsicComYMCKColorKind)i );
		
		// ｽｸﾘｰﾝ処理　SCREEN制御 TAG変換 設定レジスタの設定値を取得する.
		ps_IPRomPara->s_BinarizerReg.ul_TagChg[i] 		= getTagChg( e_ScreenMode, (THRE_AsicComYMCKColorKind)i );

		// ｽｸﾘｰﾝ処理　SCREEN制御 1200dpi2値線幅補正用属性信号変換 設定レジスタの設定値を取得する.
		ps_IPRomPara->s_BinarizerReg.ul_TagChg[i] |=  getCTagChg( e_ScreenMode, (THRE_AsicComYMCKColorKind)i )  << ( 2 * THRD_ASICCOMREG_SHIFTNUM_8BIT );

		// ｽｸﾘｰﾝ処理　SCREEN制御 ｽｸﾘｰﾝX主走査ﾏﾄﾘｸｽｻｲｽﾞ 設定レジスタの設定値を取得する.
		ps_IPRomPara->s_BinarizerReg.ul_Screen_HSize[i]    = getMatrixHSize( e_MSMode, (THRE_AsicComYMCKColorKind)i, us_ScreenCol_Mode, ps_ThreadComPara, pc_Image );
		// ｽｸﾘｰﾝ処理　SCREEN制御 ｽｸﾘｰﾝX副走査ﾏﾄﾘｸｽｻｲｽﾞ 設定レジスタの設定値を取得する.
		ps_IPRomPara->s_BinarizerReg.ul_Screen_VSize[i]	   = getMatrixVSize( e_MSMode, (THRE_AsicComYMCKColorKind)i, us_ScreenCol_Mode, ps_ThreadComPara, pc_Image );
		// ｽｸﾘｰﾝ処理　SCREEN制御 ｽｸﾘｰﾝX主走査ｱﾄﾞﾚｽｼﾌﾄ量 設定レジスタの設定値を取得する.
		ps_IPRomPara->s_BinarizerReg.ul_Screen_ShitSize[i] = getMatrixShift( e_MSMode, (THRE_AsicComYMCKColorKind)i, us_ScreenCol_Mode, ps_ThreadComPara, pc_Image );
		
		// ｽｸﾘｰﾝ処理　ｽｸﾘｰﾝ処理ｽﾙｰ選択設定レジスタの設定値を取得する.
		ps_IPRomPara->s_BinarizerReg.ul_Screen_Other[i]	= getThroughSel( e_ScreenMode, (THRE_AsicComYMCKColorKind)i );
		
	}
}

// ================================================================================================.
//! <!--機能--> スクリーン処理_誤差拡散テーブルサイズ取得
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param なし.
//! <!--戻値-->.
//! \return 誤差拡散テーブルサイズ.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  13/07/12 Sky	ZeusS対応 新規作成 IPROM分離対応.
//  15/10/06 Sky	システム統合SoC(S800)対応.
// ================================================================================================.
uint32_t THRC_S800IPRomPara_AppInConvDiv::getDithertblSize() { 
	return THRD_S800_DITHERTBL_SIZE; 
}

// ================================================================================================.
//! <!--機能--> スクリーン処理_IPRomレジスタ領域アドレス取得.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param なし.
//! <!--戻値-->.
//! \return IPRomレジスタ領域アドレス.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  13/07/12 Sky	ZeusS対応 新規作成.
//  15/10/06 Sky	システム統合SoC(S800)対応.
// ================================================================================================.
void* THRC_S800IPRomPara_AppInConvDiv::getIPRomPara() 
{ 
	return (void*)ps_IPRomPara;
}

// ================================================================================================.
//! <!--機能--> IPRomレジスタ領域アドレス取得(メッセージパラメータ).
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param なし.
//! <!--戻値-->.
//! \return IPRomレジスタ領域アドレス.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  13/07/12 Sky	ZeusS対応 新規作成.
//  15/10/06 Sky	システム統合SoC(S800)対応.
// ================================================================================================.
void THRC_S800IPRomPara_AppInConvDiv::ThrMsgParaAddrSetting() 
{ 
	// IPROMレジスタ領域のアドレス取得.
	ps_IPRomPara = ThrAppInConvDivCtr_GetS800IPRomPara();
}

//-- CMM向けレジスタ設定値取得関数群 --.
// ================================================================================================.
//! <!--機能--> CMYK　色変換ﾏﾄﾘｸｽ係数設定レジスタの設定値を取得する.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param THRE_AsicComMSMode e_MSmode ................. 画像補正モード(原稿モード).
//! \param const ST_ThreadComPara* ps_ThreadComPara ... マルチスレッド 画像転送開始メッセージパラメータ.
//! \param Bool b_4DimensionConv ...................... 4次元⇒4次元変換フラグ.
//! \param uchar uc_BankNo ............................ バンク0～2.
//! \param ushort us_MatrixAns[][3] ................... マトリクス演算結果格納テーブル.
//! \param TYPE_ColorMode e_ColorMode ................. カラーモード.
//! \param const IMGC_Image* pc_Image ................. 入力イメージ情報.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  11/09/05 Sky戸田	 新規作成.
//  12/03/05 Sky鋤柄	 IPROM機種カスタマイズ対応.
//  12/04/05 Sky山下	 IPROM機種カスタマイズ対応 WT指摘対応 テーブルデータの管理方法変更.
//  12/04/11 Sky山下	 IPROM機種カスタマイズ対応 WT指摘対応 二色カラーの場合は自動、自動以外の判別は不要なので処理を統一.
//  12/04/17 Sky世古	 IPROM機種カスタマイズ対応.UT不具合 2色カラーの場合もフルカラー時と同様に自動、自動以外の判別が必要なので、処理を元に戻した.
//  12/04/20 Sky世古	 IPROM機種カスタマイズ対応.仕様変更対応：彩度レベルに応じた調整値を格納するローカルテーブルの型をushort→ucharに修正.
//  12/06/13 Sky世古	 IPROM機種カスタマイズ対応 2色カラー対応：2色カラー濃淡判定を追加.
//  12/06/14 Sky世古	 getImage関数のコール数削減対応.
//  12/06/21 Sky世古	 IPROM機種カスタマイズ対応 カラーマッチングのみの判定をカラーマッチングとグレー補償で判定するよう修正.
//  13/03/12 Sky		ZeusS対応 DMA29用のIPROM処理(Asic30からコピー).
//  15/10/06 Sky		システム統合SoC(S800)対応.
//  18/07/20 Sky		KRQ-361 EagleSparrowの画質改善の件 (PCLの1200dpiのプリント).
//  18/10/22 Sky 		AR1065408 【Eagle/Sparrow共通】【開発提起】ChinaRed有効時1200dpiPCPrint出力が不正.
// ================================================================================================.
void THRC_S800IPRomPara_AppInConvDiv::getColorMatrix( THRE_AsicComMSMode e_MSmode, const ST_ThreadComPara* ps_ThreadComPara, Bool b_4DimensionConv, uchar uc_BankNo, ushort us_MatrixAns[][3], TYPE_ColorMode e_ColorMode, const IMGC_Image* pc_Image )
{
	IPROM_TBL_1BYTE  iprom_RegCMMTBL_1Byte  = NULL;
	IPROM_TBL_18BYTE iprom_RegCMMTBL_18Byte = NULL;
	IPROM_TBL_1BYTE  iprom_MselColorTBL = NULL;
	
	uchar uc_OMValue = 0;
	ushort us_MatrixParam[3][3] = {{0,0,0},{0,0,0},{0,0,0}};				// ﾏﾄﾘｸｽ演算用(R色0-2/G色0-2/B色0-2).
	uchar uc_Saturation[3][3] = {{0,0,0},{0,0,0},{0,0,0}};					// ﾏﾄﾘｸｽ演算用(彩度レベルに応じた調整値).
	THRS_AsicCom_ClrJudgeParam s_ClrJudgeParam;
	TYPC_PrinterImageAdjust ec_PrinterImageAdjust = ps_ThreadComPara->c_ThreadIF.c_PrinterImageAdjust;
	TYPC_2ColorMode ec_2ColorMode = ps_ThreadComPara->c_ThreadIF.c_2ColorMode;

	// ｶﾗｰﾓｰﾄﾞ判定:ｸﾞﾚｰ.
	if( TYPE_ColorModeBlack == e_ColorMode ){
		iprom_RegCMMTBL_1Byte = iprom_size1_Tables[us_MatrrixGray]->getTable(THRE_AsicComIPParam_Kind_0);						// ICCﾌﾟﾛﾌｧｲﾙﾃﾞｰﾀ取得.
	// ｶﾗｰﾓｰﾄﾞ判定:ｸﾞﾚｰ以外かつ4次元→4次元変換判定:あり.
	}else if( TYPE_ColorModeBlack != e_ColorMode && True == b_4DimensionConv ){
		iprom_RegCMMTBL_18Byte = icc_size18_Tables[us_Reg_CMM_Matrix]->getTable_4D(0);
	// ｶﾗｰﾓｰﾄﾞ判定:ｸﾞﾚｰ以外かつ4次元→4次元変換判定:なし.
	}else{
		iprom_RegCMMTBL_18Byte = icc_size18_Tables[us_Reg_CMM_Matrix]->getTable_3D(0);
	}

	// ﾌﾟﾘﾝﾀ画質設定ﾓｰﾄﾞ判定:簡易.
	if( TYPE_PrinterImageAdjustTypeSimple == ec_PrinterImageAdjust.getPrinterImageAdjustType() ){
		getImageAdjustParam( THRE_AsicComAdjustType_Simple, 0, ps_ThreadComPara, &s_ClrJudgeParam, pc_Image );		// 簡易用ﾄﾞﾗｲﾊﾞ設定情報取得.
	// ﾌﾟﾘﾝﾀ画質設定ﾓｰﾄﾞ判定:詳細.
	}else if( TYPE_PrinterImageAdjustTypeDetail == ec_PrinterImageAdjust.getPrinterImageAdjustType() ){
		switch( uc_BankNo ){
		case THRE_ASICCOM_BANKINDEX_0:		// 文字.
			getImageAdjustParam( THRE_AsicComAdjustType_Text, 0, ps_ThreadComPara, &s_ClrJudgeParam, pc_Image );		// 詳細:文字用ﾄﾞﾗｲﾊﾞ設定情報取得.
			break;
		case THRE_ASICCOM_BANKINDEX_1:		// 図/表/ｸﾞﾗﾌ.
			getImageAdjustParam( THRE_AsicComAdjustType_Graphic, 0, ps_ThreadComPara, &s_ClrJudgeParam, pc_Image );	// 詳細:図/表/ｸﾞﾗﾌ用ﾄﾞﾗｲﾊﾞ設定情報取得.
			break;
		case THRE_ASICCOM_BANKINDEX_2:		// 写真.
			getImageAdjustParam( THRE_AsicComAdjustType_Photo, 0, ps_ThreadComPara, &s_ClrJudgeParam, pc_Image );	// 詳細:写真用ﾄﾞﾗｲﾊﾞ設定情報取得.
			break;
		default:
			THRL_ThAssert( False, "THRC_S800IPRomPara_AppInConvDiv::getColorMatrix(): BankNo is illegal! uc_BankNo=%d",
				 uc_BankNo, 0, 0, 0, CFA14_DetailCode0x0C48 );
			break;
		}
	}

	// ｶﾗｰﾓｰﾄﾞ判定:ﾌﾙｶﾗｰ.
	if( TYPE_ColorModeFullColor == e_ColorMode && False == ec_2ColorMode.get2ColorOn() ){
		iprom_MselColorTBL = iprom_size1_Tables[us_Msel_Color]->getTable((THRE_AsicComIPParam_Kind)uc_BankNo);			// Msel_Colorﾃｰﾌﾞﾙ取得.
		if( TYPE_ColorMatchingTypeAuto == s_ClrJudgeParam.e_ColormatchingType && TYPE_PureBlackAuto == s_ClrJudgeParam.e_PureBlack ){
			// カラーマッチングタイプ、グレー補償ともに自動.
			if( b_4DimensionConv == False ){
				uc_OMValue = iprom_MselColorTBL[ e_MSmode ];
			}else{
				uc_OMValue = 0;			// 4次元変換実施する場合は、0固定.
			}
		}else{
			// カラーマッチングタイプ、グレー補償いずれかが自動以外.
			uc_OMValue = getOMVale( &s_ClrJudgeParam, b_4DimensionConv, iprom_MselColorTBL[ e_MSmode ] );
			THRL_SetThLog( 686, THRE_DebugLogType_CTLog, 0, False, (uintptr_t)b_4DimensionConv, (uintptr_t)e_MSmode, (uintptr_t)iprom_MselColorTBL[ e_MSmode ], (uintptr_t)s_ClrJudgeParam.e_PureBlack, (ushort)s_ClrJudgeParam.e_ColormatchingType, (uint32_t)uc_OMValue );
		}
	// ｶﾗｰﾓｰﾄﾞ判定:2色ｶﾗｰ.
	}else if( TYPE_ColorModeFullColor == e_ColorMode && True == ec_2ColorMode.get2ColorOn() ){
		// 2色カラー(文字優先).
		if( TYPE_2ColorModeDarkerText == ec_2ColorMode.get2ColorMode() ){
			// ｶﾗｰﾏｯﾁﾝｸﾞﾀｲﾌﾟ:自動.
			if( TYPE_ColorMatchingTypeAuto == s_ClrJudgeParam.e_ColormatchingType ){
				if( False == chk2ColorModeDeep() ){
					if( False == chkChinaRed( ec_2ColorMode.getMonoColor() ) ){	// 2018/10/22 Sky [EagleL]AR1065408 【Eagle/Sparrow共通】【開発提起】ChinaRed有効時1200dpiPCPrint出力が不正.
						iprom_MselColorTBL = iprom_size1_Tables[us_Msel_Color]->getTable( THRE_AsicComIPParam_Kind_3 );		// Msel_Colorﾃｰﾌﾞﾙ取得(薄い).
					}else{
						iprom_MselColorTBL = iprom_size1_Tables[us_Msel_Color]->getTable( THRE_AsicComIPParam_Kind_6 );		// Msel_Colorﾃｰﾌﾞﾙ取得(ChinaRed文書).
					}
				}else{
					iprom_MselColorTBL = iprom_size1_Tables[us_Msel_Color]->getTable( THRE_AsicComIPParam_Kind_4 );		// Msel_Colorﾃｰﾌﾞﾙ取得(濃い).
				}
				uc_OMValue = iprom_MselColorTBL[ e_MSmode ];
			// ｶﾗｰﾏｯﾁﾝｸﾞﾀｲﾌﾟ:自動以外.
			}else{
				if( False == chk2ColorModeDeep() ){
					uc_OMValue = THRE_AsicComCMMIndexParam_TwoColor;
				}else{
					uc_OMValue = THRE_AsicComCMMIndexParam_TwoColorDark;
				}
			}
		// 2色カラー(写真優先).
		}else{
			if( False == chkChinaRed( ec_2ColorMode.getMonoColor() ) ){	// 2018/10/22 Sky [EagleL]AR1065408 【Eagle/Sparrow共通】【開発提起】ChinaRed有効時1200dpiPCPrint出力が不正
				iprom_MselColorTBL = iprom_size1_Tables[us_Msel_Color]->getTable( THRE_AsicComIPParam_Kind_5 );		// 2カラー選択(写真).
			}else{
				iprom_MselColorTBL = iprom_size1_Tables[us_Msel_Color]->getTable( THRE_AsicComIPParam_Kind_7 );		// 2カラー選択(ChinaRed写真).
			}
			uc_OMValue = iprom_MselColorTBL[ e_MSmode ];
		}
	// ｶﾗｰﾓｰﾄﾞ判定:ｸﾞﾚｰ.
	}else if( TYPE_ColorModeBlack == e_ColorMode ){
		uc_OMValue = 0;
	}else{
		THRL_ThAssert( False, "THRC_S800IPRomPara_AppInConvDiv::getColorMatrix(): ColorMode is illegal! e_ColorMode=%d, 2ColorMode=%d",
			e_ColorMode, ec_2ColorMode.get2ColorOn(), 0, 0, CFA14_DetailCode0x0C49 );
	}
        
	if ( NULL != iprom_RegCMMTBL_1Byte ) {
		getMatrix_ColorBank( uc_OMValue, iprom_RegCMMTBL_1Byte, us_MatrixParam );	// 演算用ﾃﾞｰﾀ(R色0-2/G色0-2/B色0-2)取得.
	} else {
		getMatrix_ColorBank( uc_OMValue, iprom_RegCMMTBL_18Byte, us_MatrixParam );	// 演算用ﾃﾞｰﾀ(R色0-2/G色0-2/B色0-2)取得.
	}
	getSaturationData( s_ClrJudgeParam.e_Saturation, uc_Saturation );				// 演算用ﾃﾞｰﾀ(彩度レベルに応じた調整値)取得.
	getMatrixCalc( us_MatrixParam, uc_Saturation, us_MatrixAns );					// ﾏﾄﾘｸｽ演算.
}

// ================================================================================================.
//! <!--機能--> CMYK　ﾏﾄﾘｸｽ演算用ｲﾝﾃﾞｯｸｽﾊﾟﾗﾒｰﾀ取得関数.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param uchar THRS_AsicCom_ClrJudgeParam* ps_ClrJudgeParam ... 各画質調整設定.
//! \param Bool b_4DimensionConv ............................. 4次元→4次元ﾌﾗｸﾞ.
//! \param uchar uc_MSelVal .................................. MSel_Colorテーブルからの取得値.
//! <!--戻値-->.
//! \return 演算用インデックス.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  12/03/05 Sky鋤柄	 新規作成.
//  12/04/10 Sky山下	 ４次元→４次元変換も考慮するように変更.
//  12/06/19 Sky世古	 ４次元→４次元変換時は、テーブルINDEX0固定で返すよう修正.
//  12/06/21 Sky世古	 カラーマッチング、グレー補償いずれかが自動の場合のINDEX選択条件を追加.
//  12/08/28 小霜	     CQ370159の対応.
//  13/03/12 Sky		ZeusS対応 DMA29用のIPROM処理(Asic30からコピー).
//  15/10/06 Sky		システム統合SoC(S800)対応.
//  18/07/20 Sky		KRQ-361 EagleSparrowの画質改善の件 (PCLの1200dpiのプリント).
// ================================================================================================.
uchar THRC_S800IPRomPara_AppInConvDiv::getOMVale( THRS_AsicCom_ClrJudgeParam* ps_ClrJudgeParam, Bool b_4DimensionConv, uchar uc_MSelVal )
{
	uchar uc_AnsIndex = 0;
	TYPE_PureBlack e_PureBlack = TYPE_PureBlackAuto;						// グレー補償設定.

	// ｶﾗｰﾏｯﾁﾝｸﾞﾀｲﾌﾟ判定.
	if( True == b_4DimensionConv ){
		// 4次元→4次元変換実施する場合、4次元→4次元変換用テーブルINDEXは0固定で返す.
		uc_AnsIndex = 0;
	}else{
		if( TYPE_PureBlackAuto == ps_ClrJudgeParam->e_PureBlack ){
			// グレー補償設定が自動の場合、MSel_Colorの値でグレー補償OFF/ONを判定する.
			if( THRE_AsicComCMMIndexParam_SharepGrayON <= uc_MSelVal && uc_MSelVal <= THRE_AsicComCMMIndexParam_CADGrayON ){
				e_PureBlack = TYPE_PureBlackOn;
			}else if( THRE_AsicComCMMIndexParam_SharepGrayOFF <= uc_MSelVal && uc_MSelVal <= THRE_AsicComCMMIndexParam_CADGrayOFF ){
				e_PureBlack = TYPE_PureBlackOff;
			}else{
				THRL_ThAssert( False, "THRC_S800IPRomPara_AppInConvDiv::getOMVale uc_MSelVal(PureBlack) err %d", uc_MSelVal, 0, 0, 0, CFA14_DetailCode0x0C4A );
			}
		}else{
			e_PureBlack = ps_ClrJudgeParam->e_PureBlack;
		}

		// 3次元→4次元変換の場合、カラーマッチングとグレー補償設定の組み合わせに応じたINDEXを返す.
		switch( ps_ClrJudgeParam->e_ColormatchingType ){
			case TYPE_ColorMatchingTypeAuto:			// 自動.
				// カラーマッチング設定が自動の場合、MSel_Colorの値でカラーマッチングタイプを判定する.
				// CQ370159 Mselの値がWeb/CADの場合でも、アサートしない.
				if( THRE_AsicComCMMIndexParam_SharepGrayON == uc_MSelVal || THRE_AsicComCMMIndexParam_SharepGrayOFF == uc_MSelVal ){
					if( TYPE_PureBlackOn == e_PureBlack ){
						uc_AnsIndex = THRE_AsicComCMMIndexParam_SharepGrayON;	// 文書（原色優先(シャープ)）and グレー補償あり.
					}else{
						uc_AnsIndex = THRE_AsicComCMMIndexParam_SharepGrayOFF;	// 文書（原色優先(シャープ)）and グレー補償なし.
					}
				}else if( THRE_AsicComCMMIndexParam_VividGrayON == uc_MSelVal || THRE_AsicComCMMIndexParam_VividGrayOFF == uc_MSelVal ){
					if( TYPE_PureBlackOn == e_PureBlack ){
						uc_AnsIndex = THRE_AsicComCMMIndexParam_VividGrayON;	// 標準（色味強調(ビビッド)）and グレー補償あり.
					}else{
						uc_AnsIndex = THRE_AsicComCMMIndexParam_VividGrayOFF;	// 標準（色味強調(ビビッド)）and グレー補償なし.
					}
				}else if( THRE_AsicComCMMIndexParam_NaturalGrayON == uc_MSelVal || THRE_AsicComCMMIndexParam_NaturalGrayOFF == uc_MSelVal ){
					if( TYPE_PureBlackOn == e_PureBlack ){
						uc_AnsIndex = THRE_AsicComCMMIndexParam_NaturalGrayON;	// 階調再現（色差最小(ナチュラル)）and グレー補償あり.
					}else{
						uc_AnsIndex = THRE_AsicComCMMIndexParam_NaturalGrayOFF;	// 階調再現（色差最小(ナチュラル)）and グレー補償なし.
					}
				}else if( THRE_AsicComCMMIndexParam_WebGrayON == uc_MSelVal || THRE_AsicComCMMIndexParam_WebGrayOFF == uc_MSelVal ){
					if( TYPE_PureBlackOn == e_PureBlack ){
						uc_AnsIndex = THRE_AsicComCMMIndexParam_WebGrayON;		// Web and グレー補償あり.
					}else{
						uc_AnsIndex = THRE_AsicComCMMIndexParam_WebGrayOFF;		// Web and グレー補償なし.
					}
				}else if( THRE_AsicComCMMIndexParam_CADGrayON == uc_MSelVal || THRE_AsicComCMMIndexParam_CADGrayOFF == uc_MSelVal ){
					if( TYPE_PureBlackOn == e_PureBlack ){
						uc_AnsIndex = THRE_AsicComCMMIndexParam_CADGrayON;		// CAD and グレー補償あり.
					}else{
						uc_AnsIndex = THRE_AsicComCMMIndexParam_CADGrayOFF;		// CAD and グレー補償なし.
					}
				}else{
					THRL_ThAssert( False, "THRC_S800IPRomPara_AppInConvDiv::getOMVale uc_MSelVal(ColorMatching) err %d", uc_MSelVal, 0, 0, 0, CFA14_DetailCode0x0C4B );
				}
				break;
			case TYPE_ColorMatchingTypeDocument:		// 文書（原色優先(シャープ)）.
				if( TYPE_PureBlackOn == e_PureBlack ){
					uc_AnsIndex = THRE_AsicComCMMIndexParam_SharepGrayON;	// 文書（原色優先(シャープ)）and グレー補償あり.
				}else{
					uc_AnsIndex = THRE_AsicComCMMIndexParam_SharepGrayOFF;	// 文書（原色優先(シャープ)）and グレー補償なし.
				}
				break;
			case TYPE_ColorMatchingTypeStandard:		// 標準（色味強調(ビビッド)）.
				if( TYPE_PureBlackOn == e_PureBlack ){
					uc_AnsIndex = THRE_AsicComCMMIndexParam_VividGrayON;	// 標準（色味強調(ビビッド)）and グレー補償あり.
				}else{
					uc_AnsIndex = THRE_AsicComCMMIndexParam_VividGrayOFF;	// 標準（色味強調(ビビッド)）and グレー補償なし.
				}
				break;
			case TYPE_ColorMatchingTypeTonePriority:	// 階調再現（色差最小(ナチュラル)）.
				if( TYPE_PureBlackOn == e_PureBlack ){
					uc_AnsIndex = THRE_AsicComCMMIndexParam_NaturalGrayON;	// 階調再現（色差最小(ナチュラル)）and グレー補償あり.
				}else{
					uc_AnsIndex = THRE_AsicComCMMIndexParam_NaturalGrayOFF;	// 階調再現（色差最小(ナチュラル)）and グレー補償なし.
				}
				break;
			// Web,CAD,RGB⇒YMCK(2色)変換_濃い,RGB⇒YMCK(2色)変換_薄いの4種について画パラ仕様としては存在する.
			// しかし、ユーザー指定はできない組み合わせである(PS/PCLドライバで選択項目無い)ため、設定されるケースは現状存在しない.
			// 仕様変更により必要なった場合に実装を追加する.
			default:
				THRL_ThUnknownPara( False, "THRC_S800IPRomPara_AppInConvDiv::getOMVale e_ColormatchingType err %d", ps_ClrJudgeParam->e_ColormatchingType, 0, 0, 0, CFA14_DetailCode0x0C4C );
				break;
		}
	}
	return uc_AnsIndex;
}

// ================================================================================================.
//! <!--機能--> CMYK　ﾏﾄﾘｸｽ演算用ﾃﾞｰﾀ(左辺)取得補助関数 多様性の実装.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param uchar uc_OMValue              .... Reg_CMM_Matrix_ASIC30テーブル参照先インデックス.
//! \param const uchar* puc_RegCMM       .... ループインデックス.
//! \param IPROM_TBL_XXBYTE iprom_RegCMM .... マトリクス演算結果格納テーブル.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  12/04/05 Sky山下	 新規作成.
//  13/03/12 Sky		ZeusS対応 DMA29用のIPROM処理(Asic30からコピー).
// ================================================================================================.
static uchar getMatrix_ColorBank_Sub( uchar uc_OMValue, uchar uc_Cnt, IPROM_TBL_1BYTE iprom_RegCMM )
{
	return iprom_RegCMM[uc_Cnt];
}
static uchar getMatrix_ColorBank_Sub( uchar uc_OMValue, uchar uc_Cnt, IPROM_TBL_18BYTE iprom_RegCMM )
{
	return iprom_RegCMM[uc_OMValue][uc_Cnt];
}

// ================================================================================================.
//! <!--機能--> CMYK　ﾏﾄﾘｸｽ演算用ﾃﾞｰﾀ(左辺)取得関数.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param uchar uc_OMValue ............. Reg_CMM_Matrix_ASIC30テーブル参照先インデックス.
//! \param const uchar* puc_RegCMM ..... Reg_CMM_Matrix_ASIC30テーブルのアドレス.
//! \param ushort us_MatrixAns[][3] .... マトリクス演算結果格納テーブル.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  12/03/05 Sky鋤柄	 新規作成.
//  12/04/05 Sky山下	 IPROM機種カスタマイズ対応 WT指摘対応 テーブルデータの管理方法変更.
//  12/04/05 Sky山下	 IPROM機種カスタマイズ対応 WT指摘対応 演算結果の格納方法修正, 変数名変更.
//  12/05/25 Sky世古	 IPROM機種カスタマイズ対応 CT不具合No.14対応 上位と下位が入れ替わっている不具合を修正.
//  13/03/12 Sky		ZeusS対応 DMA29用のIPROM処理(Asic30からコピー).
//  15/10/06 Sky		システム統合SoC(S800)対応.
// ================================================================================================.
template <class T>
void THRC_S800IPRomPara_AppInConvDiv::getMatrix_ColorBank( uchar uc_OMValue, T iprom_RegCMM, ushort us_MatrixParam[][3] )
{
	uchar uc_Cnt = 0;		// ループカウンタ.
	uchar uc_mx = 0;		// マトリクス計算位置 x位置.
	uchar uc_my = 0;		// マトリクス計算位置 y位置.
	uchar uc_WorkData = 0;	// Reg_CMM_Matrix_ASIC30テーブル取得値Work領域.
                    
	// 以下の処理で指定テーブルの.
	//   奇数バイトをus_MatrixParam要素の上位バイトに詰める.
	//   偶数バイトをus_MatrixParam要素の下位バイトに詰める.
	for( uc_Cnt = 0; uc_Cnt < TYPE_ImageAdjustMax; uc_Cnt++ ){
		uc_WorkData = getMatrix_ColorBank_Sub( uc_OMValue, uc_Cnt, iprom_RegCMM );
		if( 0 != (uc_Cnt % 2) ){      // ２バイト(ショートサイズ分)繰り返し.
			us_MatrixParam[ uc_my ][ uc_mx ] = (ushort)( us_MatrixParam[ uc_my ][ uc_mx ] | (ushort)( uc_WorkData << THRD_ASICCOMREG_SHIFTNUM_8BIT ));	// 2byteﾃﾞｰﾀの作成が必要な為、1byte分ｼﾌﾄする.
			uc_mx++;
			if( 0 == ( uc_mx % THRD_MATRIX_SIZE )) {   // 1列分処理が完了したら次の行に移動
				uc_mx = 0; 
				uc_my++;
			}
		}else{
			us_MatrixParam[ uc_my ][ uc_mx ] = (ushort)( us_MatrixParam[ uc_my ][ uc_mx ] | uc_WorkData );
		}
	}
}

// ================================================================================================.
//! <!--機能--> CMYK　ﾏﾄﾘｸｽ演算用ﾃﾞｰﾀ(右辺)取得関数.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param TYPE_ImageAdjust e_ImageAdjust ..... 明度調整レベル.
//! \param uchar uc_Saturation_Bank2[][3] ..... 彩度調整係数（色変換ﾏﾄﾘｸｽ係数）格納テーブル.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  12/03/05 Sky鋤柄	 新規作成.
//  12/04/05 Sky山下	 IPROM機種カスタマイズ対応 WT指摘対応 変数名変更.
//  12/04/20 Sky世古	 IPROM機種カスタマイズ対応.仕様変更対応：彩度調整係数格納テーブル引数の型をushort→ucharに修正.
//  13/03/12 Sky		ZeusS対応 DMA29用のIPROM処理(Asic30からコピー).
//  15/10/06 Sky		システム統合SoC(S800)対応.
// ================================================================================================.
void THRC_S800IPRomPara_AppInConvDiv::getSaturationData( TYPE_ImageAdjust e_ImageAdjust, uchar uc_Saturation_Bank2[][3] )
{
	uchar uc_Cnt = 0;
	uchar uc_mx = 0;		// マトリクス計算位置 x位置.
	uchar uc_my = 0;		// マトリクス計算位置 y位置.
	
	IPROM_TBL_9BYTE iprom_RegCMMTBL = iprom_size9_Tables[us_CROMA_MATRIX]->getTable(THRE_AsicComIPParam_Kind_0);

	for( uc_Cnt = 0; uc_Cnt < 9; uc_Cnt++ ){	// CROMA_MATRIX_S800ﾃｰﾌﾞﾙﾃﾞｰﾀ分繰り返す "9"はﾃｰﾌﾞﾙの2次配列ｻｲｽﾞ.
		uc_Saturation_Bank2[ uc_my ][ uc_mx ] = iprom_RegCMMTBL[(uchar)e_ImageAdjust][uc_Cnt];	// []内はオフセット移行演算. "19"はﾃｰﾌﾞﾙの1次配列ｻｲｽﾞ.
		// マトリクスX軸更新判定 0から2の範囲で更新.
		uc_mx++;
		if( 0 == (uc_mx % THRD_MATRIX_SIZE)){
			// マトリクスY軸更新判定 0から2の範囲で更新.
			uc_mx = 0;
			uc_my++;
		}
	}
}

// ================================================================================================.
//! <!--機能--> CMYK　ﾏﾄﾘｸｽ演算用ﾃﾞｰﾀ取得関数.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param ushort us_DataA[][3] ..... Reg_CMM_Matrix_ASIC30テーブル取得値.
//! \param uchar uc_DataB[][3] ...... 彩度調整係数（色変換ﾏﾄﾘｸｽ係数）テーブル取得値.
//! \param ushort us_CalcAns[][3] ... マトリクス演算結果格納テーブル.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  12/03/05 Sky鋤柄	 新規作成.
//  12/04/05 Sky山下	 Warning対応.
//  12/04/09 Sky山下	 IPROM機種カスタマイズ対応 WT指摘対応 変数コメント修正.
//  12/04/17 Sky世古	 IPROM機種カスタマイズ対応.UT不具合対応.
//						 演算中にushort最大値を超えることがあるため、演算中の値はulongで保持.
//						 最終的に結果用変数に演算結果設定時、演算結果がushortを超えないか確認してから設定するよう修正.
//  12/04/20 Sky世古	 IPROM機種カスタマイズ対応.仕様変更対応
//						 彩度調整係数格納テーブル引数の型をushort→ucharに修正.
//						 演算前に各演算対象データを2の補数→整数変換し、演算後は閾値補正後、整数→2の補数変換するよう修正.
//	12/06/19 Sky窪川	 正の数の場合も2の補数演算していたので修正.
//	12/08/23 Sky仲川	 符号なし/あり変換時に負数に対し補数演算し、正数となった状態で使用していたので修正.
//  13/03/12 Sky		ZeusS対応 DMA29用のIPROM処理(Asic30からコピー).
//  15/10/06 Sky		システム統合SoC(S800)対応.
// ================================================================================================.
void THRC_S800IPRomPara_AppInConvDiv::getMatrixCalc(ushort us_DataA[][3], uchar uc_DataB[][3], ushort us_CalcAns[][3])
{
	uchar uc_CntA = 0;			// 演算結果のY軸/入力データAのY軸.
	uchar uc_CntB = 0;			// 演算結果のX軸/入力データBのX軸.
	uchar uc_CntC = 0;			// 入力データAのX軸/入力データBのY軸.
	int32_t sl_CalcWork = 0;		// 演算結果work領域.
	short ss_CalcAns = 0;		// 演算結果(整数⇒2の補数変換前用).
	short ss_DataA = 0;			// Reg_CMM_Matrix_ASIC30テーブル取得データwork領域(2の補数⇒整数変換後).
	char sc_DataB = 0;			// 彩度調整係数テーブル取得データwork領域(2の補数⇒整数変換後).

	// 演算.
	for( uc_CntA = 0; uc_CntA < THRD_MATRIX_SIZE; uc_CntA++){	// 縦軸分繰り返す.
		for( uc_CntB = 0; uc_CntB < THRD_MATRIX_SIZE; uc_CntB++ ){	 // 横軸分繰り返す.
			for( uc_CntC = 0; uc_CntC < THRD_MATRIX_SIZE; uc_CntC++ ){	// 1演算(Ans[0][0])に必要な行列計算分繰り返す.
				if( (us_DataA[ uc_CntA ][ uc_CntC ] & 0x8000) == 0x8000 ) {	// 最上位ビットが1の場合負の数なので補数演算.
					ss_DataA = (short)((short)THRD_ChgComplementToInteger2BYTE(us_DataA[ uc_CntA ][ uc_CntC ]) * (-1));
				} else {
					ss_DataA = (short)us_DataA[ uc_CntA ][ uc_CntC ];
				}
				if( (uc_DataB[ uc_CntC ][ uc_CntB ] & 0x80) == 0x80 ) {	// 最上位ビットが1の場合負の数なので補数演算.
					sc_DataB = (char)((char)THRD_ChgComplementToInteger1BYTE(uc_DataB[ uc_CntC ][ uc_CntB ]) * (-1));
				} else {
					sc_DataB = (char)uc_DataB[ uc_CntC ][ uc_CntB ];
				}
				sl_CalcWork = sl_CalcWork + ss_DataA * sc_DataB;
			}
			sl_CalcWork = sl_CalcWork / THRD_ASICCOM_COLORMTRXDATA0x40;
			// 演算結果の閾値補正.
			if( sl_CalcWork > THRD_ASICCOM_SHORT_MAX ){
				ss_CalcAns = THRD_ASICCOM_SHORT_MAX;
			}else if( sl_CalcWork < THRD_ASICCOM_SHORT_MIN ){
				ss_CalcAns = THRD_ASICCOM_SHORT_MIN;
			}else{
				ss_CalcAns = (short)sl_CalcWork;
			}
			if( ss_CalcAns < 0 ) {		// 負の数の場合は補数演算してASICに設定.
				us_CalcAns[ uc_CntA ][ uc_CntB ] = (ushort)THRD_ChgIntegerToComplement2BYTE(ss_CalcAns*(-1));
			} else {
				us_CalcAns[ uc_CntA ][ uc_CntB ] = (ushort)ss_CalcAns;
			}
			sl_CalcWork = 0;
		}
	}
}

// ================================================================================================.
//! <!--機能--> CMYK　ﾏﾄﾘｸｽ演算結果設定関数.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param uchar uc_RegNo .................. レジスタインデックス.
//! \param ushort us_MatrixCalcAns[][3] ..... マトリクス演算結果格納テーブル.
//! <!--戻値-->.
//! \return レジスタ設定値.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  12/03/05 Sky鋤柄	 新規作成.
//  13/03/12 Sky		ZeusS対応 DMA29用のIPROM処理(Asic30からコピー).
//  15/10/06 Sky		システム統合SoC(S800)対応.
// ================================================================================================.
uint32_t THRC_S800IPRomPara_AppInConvDiv::getColorMatrix_Reg( uchar uc_RegNo, ushort us_MatrixCalcAns[][3] )
{
	uint32_t ul_ColorMatrix = 0;

	switch( uc_RegNo ){
	case THRE_ASICCOM_REGINDEX_0:
		ul_ColorMatrix |= us_MatrixCalcAns[0][0];
		ul_ColorMatrix |= us_MatrixCalcAns[0][1] << THRD_ASICCOMREG_SHIFTNUM_16BIT;
		break;
	case THRE_ASICCOM_REGINDEX_1:	// uc_RegNoが奇数の場合上位16bitは設定しない.
		ul_ColorMatrix |= us_MatrixCalcAns[0][2];
		break;
	case THRE_ASICCOM_REGINDEX_2:
		ul_ColorMatrix |= us_MatrixCalcAns[1][0];
		ul_ColorMatrix |= us_MatrixCalcAns[1][1] << THRD_ASICCOMREG_SHIFTNUM_16BIT;
		break;
	case THRE_ASICCOM_REGINDEX_3:	// uc_RegNoが奇数の場合上位16bitは設定しない.
		ul_ColorMatrix |= us_MatrixCalcAns[1][2];
		break;
	case THRE_ASICCOM_REGINDEX_4:
		ul_ColorMatrix |= us_MatrixCalcAns[2][0];
		ul_ColorMatrix |= us_MatrixCalcAns[2][1] << THRD_ASICCOMREG_SHIFTNUM_16BIT;
		break;
	case THRE_ASICCOM_REGINDEX_5:
		ul_ColorMatrix |= us_MatrixCalcAns[2][2];
		break;
	default:
		THRL_ThAssert( False, "THRC_S800IPRomPara_AppInConvDiv::getColorMatrix_Reg(): RegNo is illegal! RegNo=%d", uc_RegNo, 0, 0, 0, CFA14_DetailCode0x0C4D );
		break;
	}

	return ul_ColorMatrix;
}


