// ================================================================================================.
//! <!--機能--> CMYK　4次元LUT用設定レジスタの設定値を取得する.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param THRE_AsicComCmmMode e_mode ... CMM画像変換モード.
//! <!--戻値-->.
//! \return レジスタ設定値.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  11/09/05 Sky戸田	 新規作成.
//  12/03/05 Sky鋤柄	 IPROM機種カスタマイズ対応.
//  12/04/05 Sky山下	 IPROM機種カスタマイズ対応 WT指摘対応 テーブルデータの管理方法変更.
//  13/03/12 Sky		ZeusS対応 DMA29用のIPROM処理(Asic30からコピー).
//  15/10/06 Sky		システム統合SoC(S800)対応.
// ================================================================================================.
uint32_t THRC_S800IPRomPara_AppInConvDiv::get4DimensionLUT( THRE_AsicComCmmMode e_mode )
{
	IPROM_TBL_4BYTE iprom_TBL = iprom_size4_Tables[us_4DimensionLUT]->getTable(THRE_AsicComIPParam_Kind_0);	// p_4DimensionLUT.

	uint32_t ul_4DimensionLUT = 0;
	for( int32_t i=0; i<THRD_S800REG_SETNUM_4BYTE; i++ ){
		ul_4DimensionLUT |= iprom_TBL[e_mode][i] << (i*THRD_ASICCOMREG_SHIFTNUM_8BIT);	// []内はオフセット移行演算. "4"はﾃｰﾌﾞﾙの1次配列ｻｲｽﾞ.
	}
	return ul_4DimensionLUT;
}

