//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  11/09/05 Sky戸田	 新規作成.
//  12/03/05 Sky鋤柄	 IPROM機種カスタマイズ対応.
//  12/04/05 Sky山下	 IPROM機種カスタマイズ対応 WT指摘対応 テーブルデータの管理方法変更.
