// ================================================================================================.
uint32_t THRC_S800IPRomPara_AppInConvDiv::getWhiteChange( THRE_AsicComCmmMode e_mode, THRE_AsicComIPParam_Kind e_kind )
{
	uint32_t ul_WhiteChange = 0;
	IPROM_TBL_4BYTE iprom_TBL = iprom_size4_Tables[us_WhiteChange]->getTable(e_kind);	// p_4DimensionLUT.

	for( uchar i=0; i<THRD_S800REG_SETNUM_4BYTE; i++ ){
		ul_WhiteChange |= iprom_TBL[e_mode][i] << (i * THRD_ASICCOMREG_SHIFTNUM_8BIT);	// []内はオフセット移行演算. "4"はﾃｰﾌﾞﾙの1次配列ｻｲｽﾞ.
	}
	return ul_WhiteChange;
}

