// ================================================================================================.
//! <!--機能--> CMYK　ﾓﾉｶﾗｰ用Y,M,C,Kﾃﾞｰﾀ変調ﾃﾞｰﾀ設定レジスタの設定値を取得する.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param THRE_AsicComCmmMode e_mode ......... CMM画像変換モード.
//! \param THRE_Asic30YMCKColorKind e_kind ... YMCK色種類.
//! <!--戻値-->.
//! \return レジスタ設定値.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  11/09/05 Sky戸田	 新規作成.
