// ================================================================================================.
//! <!--機能--> ｽｸﾘｰﾝ処理　γ補正ﾃｰﾌﾞﾙ 設定レジスタの設定値を取得する.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param THRE_AsicComScreenMode e_Mode ...... スクリーンモード.
//! \param THRE_AsicComYMCKColorKind e_kind ... YMCK色種類.
//! <!--戻値-->.
//! \return レジスタ設定値.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  11/09/05 Sky戸田	 新規作成.
//  12/03/05 Sky鋤柄	 IPROM機種カスタマイズ対応.
//  12/04/05 Sky山下	 IPROM機種カスタマイズ対応 WT指摘対応 テーブルデータの管理方法変更.
//  12/04/10 Sky山下	 アクセラレータIPROMカスタマイズ対応 関数名をgetGammaTable->getGammaScreenTableに変更.
//  12/05/02 Sky窪川	 IPROM機種カスタマイズ対応 CT問題点 Asic777_GammaEnテーブルをYMCK色種別で参照していたので修正.
//  12/09/20 Sky山下	 IPROM設計見直し 現状、スクリーンOnでスクリーンγ補正をスルーにすることはありえないので
//                                       Asic777_GammaEnのテーブルを利用せず0x00固定でセットするように変更.
//  13/03/12 Sky		ZeusS対応 DMA29用のIPROM処理(Asic30からコピー).
//  14/06/22 Sky         IPROM(スクリーン)対応.
//  15/10/06 Sky		システム統合SoC(S800)対応.
// ================================================================================================.
uint32_t THRC_S800IPRomPara_AppInConvDiv::getGammaScreenTable( THRE_AsicComScreenMode e_mode, THRE_AsicComYMCKColorKind e_kind )
{
	uint32_t ul_GammaTable = 0;
	IPROM_TBL_1BYTE iprom_TBL    = iprom_size1_Tables[us_GammaTableScreen]->getTable(e_kind);
	IPROM_TBL_1BYTE iprom_GmmmaEnTBL    = iprom_size1_Tables[us_GammaEn]->getTable(0);

	ul_GammaTable |= iprom_TBL[e_mode];
	//現状、テーブルは存在するが、スクリーンONでガンマ補正をスルーすることがないので0x00固定でセットする.	
	ul_GammaTable |= iprom_GmmmaEnTBL[0] << (1 * THRD_ASICCOMREG_SHIFTNUM_8BIT);	

	return ul_GammaTable;
}

