//! <!--履歴-->.
//  12/03/21 世古	IPROM機種カスタマイズ対応：新規作成.
//  13/03/12 Sky		ZeusS対応 DMA29用のIPROM処理(Asic30からコピー).
//  15/10/06 Sky	 	システム統合SoC(S800)対応.
// ================================================================================================.
void THRC_S800IPRomPara_AppInConvDiv::getCMMInputTableInfo( THRE_ASICCOM_MEMMAP_TblKind e_TblId, THRS_IPRomInputTblInfoCom &s_Param )
{
	struct THRS_IPRomInputTblInfo {
		THRE_ASICCOM_MEMMAP_TblKind	e_TblId;				// テーブルID.
		THRS_IPRomInputTblInfoCom s_Param;				// 取得情報.
	};
	static THRS_IPRomInputTblInfo s_ParamCode[] = {
		// 取得サイズが「0」の場合は非搭載.
		//Table種別						  取得開始Index				取得サイズ						ASICサイズ.
		{ THRE_ASICCOM_MEMMAP_LUT0,		{ 0,						THRE_AsicCom_AsicSIZE732,		THRE_AsicCom_AsicSIZE1024 }},
		{ THRE_ASICCOM_MEMMAP_LUT1,		{ 0,						THRE_AsicCom_AsicSIZE512,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_LUT2,		{ 0,						THRE_AsicCom_AsicSIZE512,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_LUT3,		{ 0,						THRE_AsicCom_AsicSIZE512,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_LUT4,		{ 0,						THRE_AsicCom_AsicSIZE512,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_LUT5,		{ 0,						THRE_AsicCom_AsicSIZE512,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_LUT6,		{ 0,						THRE_AsicCom_AsicSIZE512,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_LUT7,		{ 0,						THRE_AsicCom_AsicSIZE512,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_LUT8,		{ THRE_AsicCom_AsicSIZE512,	THRE_AsicCom_AsicSIZE220,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_LUT9,		{ THRE_AsicCom_AsicSIZE512,	THRE_AsicCom_AsicSIZE220,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_LUT10,		{ THRE_AsicCom_AsicSIZE512,	THRE_AsicCom_AsicSIZE220,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_LUT11,		{ THRE_AsicCom_AsicSIZE512,	THRE_AsicCom_AsicSIZE220,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_LUT12,		{ THRE_AsicCom_AsicSIZE512,	THRE_AsicCom_AsicSIZE220,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_LUT13,		{ THRE_AsicCom_AsicSIZE512,	THRE_AsicCom_AsicSIZE220,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_LUT14,		{ 0,						0,								THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_LUT15,		{ 0,						0,								THRE_AsicCom_AsicSIZE256  }},
		{ THRE_ASICCOM_MEMMAP_GAMMA,		{ 0,						THRE_AsicCom_AsicSIZE256,		THRE_AsicCom_AsicSIZE256  }},
		{ THRE_ASICCOM_MEMMAP_LUT0_4D,	{ 0,						THRE_AsicCom_AsicSIZE1024,		THRE_AsicCom_AsicSIZE1024 }},
		{ THRE_ASICCOM_MEMMAP_LUT1_4D,	{ 0,						THRE_AsicCom_AsicSIZE512,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_LUT2_4D,	{ 0,						THRE_AsicCom_AsicSIZE512,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_LUT3_4D,	{ 0,						THRE_AsicCom_AsicSIZE512,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_LUT4_4D,	{ 0,						THRE_AsicCom_AsicSIZE512,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_LUT5_4D,	{ 0,						THRE_AsicCom_AsicSIZE512,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_LUT6_4D,	{ 0,						THRE_AsicCom_AsicSIZE512,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_LUT7_4D,	{ 0,						THRE_AsicCom_AsicSIZE512,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_LUT8_4D,	{ 0,						THRE_AsicCom_AsicSIZE512,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_LUT9_4D,	{ 0,						THRE_AsicCom_AsicSIZE512,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_LUT10_4D,	{ 0,						THRE_AsicCom_AsicSIZE512,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_LUT11_4D,	{ 0,						THRE_AsicCom_AsicSIZE512,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_LUT12_4D,	{ 0,						THRE_AsicCom_AsicSIZE512,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_LUT13_4D,	{ 0,						THRE_AsicCom_AsicSIZE512,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_LUT14_4D,	{ 0,						THRE_AsicCom_AsicSIZE512,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_LUT15_4D,	{ 0,						THRE_AsicCom_AsicSIZE256,		THRE_AsicCom_AsicSIZE256  }},
		{ THRE_ASICCOM_MEMMAP_GAMMA_4D,	{ 0,						THRE_AsicCom_AsicSIZE256,		THRE_AsicCom_AsicSIZE256  }},
		{ THRE_ASICCOM_MEMMAP_EDGE_CRCT,	{ 0,						THRE_AsicCom_AsicSIZE2048,		THRE_AsicCom_AsicSIZE2048 }},
		{ THRE_ASICCOM_MEMMAP_MTF_CTRL,	{ 0,						THRE_AsicCom_AsicSIZE512,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_EDGE_V,	{ 0,						THRE_AsicCom_AsicSIZE256,		THRE_AsicCom_AsicSIZE256  }},
		{ THRE_ASICCOM_MEMMAP_EDGE_MID,	{ 0,						THRE_AsicCom_AsicSIZE256,		THRE_AsicCom_AsicSIZE256  }},
		{ THRE_ASICCOM_MEMMAP_GAMMA_GA,	{ 0,						THRE_AsicCom_AsicSIZE512,		THRE_AsicCom_AsicSIZE512  }},
		{ THRE_ASICCOM_MEMMAP_GAMMA_CN,	{ 0,						THRE_AsicCom_AsicSIZE512,		THRE_AsicCom_AsicSIZE512  }},
	};

	uchar uc_Idx = 0;
	uchar uc_IndexMax = sizeof(s_ParamCode)/sizeof(THRS_IPRomInputTblInfo);
	for( uc_Idx=0; uc_Idx<uc_IndexMax; uc_Idx++ ){
		if( s_ParamCode[uc_Idx].e_TblId == e_TblId ){
			break;
		}
	}

	THRL_ThAssert( uc_Idx < uc_IndexMax,
		"THRC_S800IPRomPara_AppInConvDiv::getCMMInputTableInfo() Table search NG. e_TblId=%d" , e_TblId, 0, 0, 0, CFA14_DetailCode0x0C54 );

	s_Param = s_ParamCode[uc_Idx].s_Param;
	return;
}

// ================================================================================================.
//! <!--機能--> バーコード補正_レジスタ設定.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param THRS_MsgStartAppInConvDivProcIfArg* ps_MsgStartImageConv  Msgパラメータ.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  16/03/18 Sky	バーコード属性対応.
//  17/04/07 Sky	ZeusSMLKPF対応.
// ================================================================================================.
void THRC_S800IPRomPara_AppInConvDiv::setBarcodeReg( uintptr_t ul_Param )
{
	THRS_MsgStartAppInConvDivProcIfArg* ps_MsgStartImageConv = (THRS_MsgStartAppInConvDivProcIfArg*)ul_Param;
	uchar i = 0;
	uchar uc_colorTbl = 0;

	memset( &ps_IPRomPara->s_BarcodeReg, 0, sizeof(THRS_BarcodeReg_AppInConvDiv) );

	switch( ps_MsgStartImageConv->s_BufImgInfo.e_ImageColor  )
	{
		// PCLテーブルを選択.
		case IMGE_ImageColor_RGB_ATT2:
		case IMGE_ImageColor_Light_2:
			uc_colorTbl = 0;
			break;

		// PSテーブルを選択.
		case IMGE_ImageColor_YMCK_Att2:
		case IMGE_ImageColor_Density_2:
			uc_colorTbl = 4;
			break;

		default:
			break;
	}

	for( i=0; i<THRD_S800REG_SETNUM_4BYTE; i++ ){ 
		ps_IPRomPara->s_BarcodeReg.ul_Bk_A_YMCK |= S800_BC_TAGCHG_SYSTEM[ uc_colorTbl ][i] << (i * THRD_S800REG_SIFTNUM_8BIT);
	}

	for( i=0; i<THRD_S800REG_SETNUM_4BYTE; i++ ){ 
		ps_IPRomPara->s_BarcodeReg.ul_Bk_B_YMCK |= S800_BC_TAGCHG_SYSTEM[ uc_colorTbl+1 ][i] << (i * THRD_S800REG_SIFTNUM_8BIT);
	}

	for( i=0; i<THRD_S800REG_SETNUM_4BYTE; i++ ){ 
		ps_IPRomPara->s_BarcodeReg.ul_Wh_YMCK |= S800_BC_TAGCHG_SYSTEM[ uc_colorTbl+2 ][i] << (i * THRD_S800REG_SIFTNUM_8BIT);
	}

	for( i=0; i<THRD_S800REG_SETNUM_4BYTE; i++ ){ 
		ps_IPRomPara->s_BarcodeReg.ul_Permission |= S800_BC_TAGCHG_SYSTEM[ uc_colorTbl+3 ][i] << (i * THRD_S800REG_SIFTNUM_8BIT);
	}
}

