// ================================================================================================.
//! <!--機能--> 予備圧縮レジスタテーブル値設定関数.
//! <!--------------------------------------------------------------------------------------------->.
//! <!--引数-->.
//! \param THRS_PreCompReg* s_PreCompReg ... 予備圧縮レジスタテーブルデータ設定値ポインタ.
//! \param THRE_AppID e_AppID .............. アプリ種別.
//! \param Bool b_PreComp .................. 予備圧縮判定結果.
//! <!--戻値-->.
//! \return なし.
//! <!--詳細-->.
//! \n.
//! <!--履歴-->.
//  2013/04/04 谷口	ZeusS対応 予備圧縮のIPROM設定.
//  [メモ] ただし、IPROMの仕様未確定のため、暫定版。仕様確定後、検討必要あり!!
//  2013/08/07 Sky 予備圧縮レジスタ対応.
//  2014/06/04 Sky IPROM(予備圧縮)対応.
//  2014/09/30	Sky		Asic2014対応.
//  2015/10/06	Sky	 	システム統合SoC(S800)対応.
//  2016/03/18	Sky		スキュー補正対応.
// ================================================================================================.
void THRC_S800IPRomPara_ExtIn::setPreCompRegTable( THRS_PreCompReg* s_PreCompReg, THRE_AppID e_AppID, Bool b_PreComp )
{
	uchar uc_BTC_Mode = 0;	//先頭のテーブルを使用のため固定値。残りはダミーデータ.
	uchar uc_Mode = 4;	//初期値はスルー設定.

	memset( s_PreCompReg, 0, sizeof(THRS_PreCompReg));

	if ( True == b_PreComp ) {
		switch(e_AppID)
		{
			case THRE_AppID_Copy:
				uc_Mode = 0;
				break;
			case THRE_AppID_InternalScan:
				uc_Mode = 1;
				break;
			case THRE_AppID_ExternalPrint:
				uc_Mode = 2;
				break;
			default:	//スルー.
				uc_Mode = 4;
				break;
		}

		_SET_BYTE( s_PreCompReg->ul_BTCPMODE , S800_BTC_MODE_SYSTEM[uc_BTC_Mode], 0 );
		
		_SET_BYTE( s_PreCompReg->ul_BTCPSEL0 , S800_BTC_SEL_SYSTEM[uc_Mode][0], 0 );
		_SET_BYTE( s_PreCompReg->ul_BTCPSEL0 , S800_BTC_SEL_SYSTEM[uc_Mode][1], 8 );
		
		_SET_BYTE( s_PreCompReg->ul_BTCPSEL1 , S800_BTC_SEL_SYSTEM[uc_Mode][0], 0 );
		_SET_BYTE( s_PreCompReg->ul_BTCPSEL1 , S800_BTC_SEL_SYSTEM[uc_Mode][1], 8 );
		
		_SET_BYTE( s_PreCompReg->ul_BTCPSEL2 , S800_BTC_SEL_SYSTEM[uc_Mode][0], 0 );
		_SET_BYTE( s_PreCompReg->ul_BTCPSEL2 , S800_BTC_SEL_SYSTEM[uc_Mode][1], 8 );
	}
}
